/* From less1-1.html */

        /* ===== CSS VARIABLES & THEME ===== */
        :root {
            --navy: #001f3f;
            --teal: #00d4ff;
            --light-gray: #f5f7fa;
            --white: #ffffff;
            --shadow: 0 4px 12px rgba(0, 31, 63, 0.1);
            --shadow-hover: 0 8px 20px rgba(0, 31, 63, 0.15);
            --border-radius: 12px;
            --transition: all 0.3s ease;
            --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
        }

        /* ===== RESET & BASE STYLES ===== */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-primary);
            background: var(--light-gray);
            color: var(--navy);
            line-height: 1.6;
        }

        /* ===== HEADER ===== */
        header {
            position: sticky;
            top: 0;
            z-index: 1000;
            background: var(--white);
            box-shadow: var(--shadow);
            padding: 1rem 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            display: flex;
            align-items: center;
            text-decoration: none;
            cursor: pointer;
            transition: var(--transition);
        }

        .logo img {
            height: 40px;
            width: auto;
            margin-right: 0.75rem;
        }

        .logo-text {
            font-weight: 700;
            font-size: 1.25rem;
            color: var(--navy);
        }

        .logo:hover {
            transform: translateY(-2px);
        }

        /* ===== STICKY NAVIGATION (LESSON MAP) ===== */
        .sticky-nav {
            position: sticky;
            top: 68px;
            z-index: 999;
            background: var(--navy);
            box-shadow: var(--shadow);
            padding: 0;
            overflow-x: auto;
        }

        .lesson-map {
            display: flex;
            gap: 0;
            list-style: none;
            padding: 0;
            margin: 0;
            min-width: max-content;
            padding: 0 2rem;
        }

        .lesson-map li {
            margin: 0;
        }

        .lesson-map a {
            display: inline-block;
            padding: 1rem 1.5rem;
            color: var(--white);
            text-decoration: none;
            border-bottom: 3px solid transparent;
            transition: var(--transition);
            cursor: pointer;
            font-size: 0.95rem;
            font-weight: 500;
        }

        .lesson-map a:hover,
        .lesson-map a.active {
            border-bottom-color: var(--teal);
            color: var(--teal);
        }

        /* ===== MAIN CONTENT ===== */
        main {
            max-width: 900px;
            margin: 3rem auto;
            padding: 0 2rem;
        }

        section {
            background: var(--white);
            border-radius: var(--border-radius);
            margin-bottom: 2rem;
            box-shadow: var(--shadow);
            overflow: hidden;
        }

        .section-header {
            padding: 2rem;
            background: linear-gradient(135deg, var(--navy), #003d5c);
            color: var(--white);
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
            user-select: none;
            transition: var(--transition);
        }

        .section-header:hover {
            background: linear-gradient(135deg, #003d5c, var(--navy));
        }

        .section-header h2 {
            font-size: 1.5rem;
            margin: 0;
        }

        .toggle-icon {
            font-size: 1.5rem;
            transition: transform 0.3s ease;
        }

        .section-header.collapsed .toggle-icon {
            transform: rotate(-90deg);
        }

        .section-content {
            padding: 2rem;
            max-height: 2000px;
            overflow: hidden;
            transition: max-height 0.4s ease, padding 0.4s ease;
        }

        .section-content.hidden {
            max-height: 0;
            padding: 0 2rem;
            overflow: hidden;
        }

        /* ===== VIDEO SECTION ===== */
        .video-container {
            position: relative;
            width: 100%;
            padding-bottom: 56.25%; /* 16:9 aspect ratio */
            height: 0;
            overflow: hidden;
            border-radius: var(--border-radius);
            background: var(--navy);
            margin-bottom: 1.5rem;
        }

        .video-container iframe {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            border: none;
        }

        /* ===== VIRTUAL LAB SECTION ===== */
        .lab-zone {
            background: linear-gradient(135deg, #f0f4f8, #e8f1f7);
            border: 2px dashed var(--teal);
            border-radius: var(--border-radius);
            padding: 2rem;
            text-align: center;
            margin-bottom: 1.5rem;
            min-height: 300px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
        }

        .lab-canvas {
            width: 100%;
            height: 250px;
            background: var(--white);
            border-radius: var(--border-radius);
            border: 1px solid #ddd;
            margin-bottom: 1rem;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--teal), #00b8d4);
            color: var(--navy);
            border: none;
            padding: 0.75rem 2rem;
            border-radius: var(--border-radius);
            font-weight: 600;
            cursor: pointer;
            transition: var(--transition);
            font-size: 1rem;
            box-shadow: var(--shadow);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-hover);
        }

        .btn-primary:active {
            transform: translateY(0);
        }

        /* ===== THEORY SECTION ===== */
        .theory-content {
            font-size: 1rem;
            line-height: 1.8;
        }

        .theory-content h3 {
            color: var(--navy);
            margin-top: 1.5rem;
            margin-bottom: 0.75rem;
            font-size: 1.25rem;
        }

        .theory-content h3:first-child {
            margin-top: 0;
        }

        .key-term {
            background: #fff3cd;
            padding: 0.2rem 0.5rem;
            border-radius: 4px;
            font-weight: 600;
            color: var(--navy);
        }

        .formula-box {
            background: #f0f4f8;
            border-left: 4px solid var(--teal);
            padding: 1rem;
            margin: 1.5rem 0;
            border-radius: var(--border-radius);
            font-family: 'Courier New', monospace;
            overflow-x: auto;
        }

        .worked-example {
            background: #f9f9f9;
            border-radius: var(--border-radius);
            padding: 1.5rem;
            margin: 1.5rem 0;
            border: 1px solid #e0e0e0;
        }

        .worked-example strong {
            color: var(--navy);
        }

        .worked-example p {
            margin: 0.5rem 0;
        }

        /* ===== QUIZ SECTION ===== */
        .quiz-container {
            margin-top: 1.5rem;
        }

        .quiz-question {
            background: #f5f7fa;
            padding: 1.5rem;
            border-radius: var(--border-radius);
            margin-bottom: 1.5rem;
            border-left: 4px solid var(--teal);
        }

        .quiz-question h4 {
            color: var(--navy);
            margin-bottom: 1rem;
            font-size: 1.1rem;
        }

        .quiz-options {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .quiz-option {
            padding: 0.75rem 1rem;
            border: 2px solid #ddd;
            border-radius: 8px;
            cursor: pointer;
            transition: var(--transition);
            background: var(--white);
            font-weight: 500;
        }

        .quiz-option:hover {
            border-color: var(--teal);
            background: #f0f4f8;
        }

        .quiz-option.selected {
            border-color: var(--teal);
            background: #f0f4f8;
        }

        .quiz-option.correct {
            border-color: #28a745;
            background: #d4edda;
            color: #155724;
        }

        .quiz-option.incorrect {
            border-color: #dc3545;
            background: #f8d7da;
            color: #721c24;
        }

        .quiz-feedback {
            margin-top: 1rem;
            padding: 1rem;
            border-radius: 8px;
            display: none;
            font-weight: 500;
        }

        .quiz-feedback.show {
            display: block;
        }

        .quiz-feedback.correct {
            background: #d4edda;
            color: #155724;
            border: 1px solid #c3e6cb;
        }

        .quiz-feedback.incorrect {
            background: #f8d7da;
            color: #721c24;
            border: 1px solid #f5c6cb;
        }

        /* ===== LIVE TUTOR SECTION ===== */
        .tutor-cta {
            background: linear-gradient(135deg, var(--navy), #003d5c);
            color: var(--white);
            padding: 2rem;
            border-radius: var(--border-radius);
            text-align: center;
            margin-top: 2rem;
        }

        .tutor-cta h3 {
            color: var(--white);
            margin-bottom: 1rem;
        }

        .btn-secondary {
            background: var(--teal);
            color: var(--navy);
            border: none;
            padding: 0.75rem 2rem;
            border-radius: var(--border-radius);
            font-weight: 600;
            cursor: pointer;
            transition: var(--transition);
            font-size: 1rem;
        }

        .btn-secondary:hover {
            background: #00b8d4;
            transform: translateY(-2px);
        }

        /* ===== FLOATING TUTOR BUTTON ===== */
        .floating-tutor {
            position: fixed;
            bottom: 2rem;
            right: 2rem;
            background: var(--teal);
            color: var(--navy);
            width: 60px;
            height: 60px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.5rem;
            cursor: pointer;
            box-shadow: var(--shadow-hover);
            transition: var(--transition);
            z-index: 900;
        }

        .floating-tutor:hover {
            transform: scale(1.1);
            background: #00b8d4;
        }

        /* ===== MODAL ===== */
        .modal {
            display: none;
            position: fixed;
            z-index: 2000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.5);
            animation: fadeIn 0.3s ease;
        }

        .modal.show {
            display: flex;
            align-items: center;
            justify-content: center;
        }

        @keyframes fadeIn {
            from { opacity: 0; }
            to { opacity: 1; }
        }

        .modal-content {
            background: var(--white);
            border-radius: var(--border-radius);
            padding: 2rem;
            max-width: 500px;
            width: 90%;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
            animation: slideUp 0.3s ease;
        }

        @keyframes slideUp {
            from { transform: translateY(50px); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
        }

        .modal-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 1.5rem;
        }

        .modal-header h2 {
            color: var(--navy);
            margin: 0;
        }

        .close-btn {
            font-size: 2rem;
            cursor: pointer;
            background: none;
            border: none;
            color: #999;
            transition: color 0.3s;
        }

        .close-btn:hover {
            color: var(--navy);
        }

        /* ===== FOOTER / LESSON NAVIGATION ===== */
        .lesson-nav {
            background: var(--navy);
            color: var(--white);
            padding: 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 1rem;
            margin-top: 3rem;
            border-radius: var(--border-radius) var(--border-radius) 0 0;
        }

        .nav-btn {
            padding: 0.75rem 1.5rem;
            border: 2px solid var(--teal);
            background: transparent;
            color: var(--white);
            border-radius: 8px;
            cursor: pointer;
            font-weight: 600;
            transition: var(--transition);
            text-decoration: none;
            display: inline-block;
        }

        .nav-btn:hover {
            background: var(--teal);
            color: var(--navy);
        }

        .nav-btn.primary {
            background: var(--teal);
            color: var(--navy);
        }

        .nav-btn.primary:hover {
            background: #00b8d4;
        }

        .nav-center {
            text-align: center;
            flex: 1;
        }

        /* ===== RESPONSIVE DESIGN ===== */
        @media (max-width: 768px) {
            header {
                flex-direction: column;
                gap: 1rem;
                padding: 1rem;
            }

            .sticky-nav {
                top: auto;
                overflow-x: auto;
            }

            .lesson-map {
                padding: 0 1rem;
            }

            .lesson-map a {
                padding: 0.75rem 1rem;
                font-size: 0.85rem;
            }

            main {
                margin: 2rem auto;
                padding: 0 1rem;
            }

            .section-header {
                padding: 1.5rem;
            }

            .section-header h2 {
                font-size: 1.25rem;
            }

            .section-content {
                padding: 1.5rem;
            }

            .lesson-nav {
                flex-direction: column;
                padding: 1.5rem 1rem;
            }

            .nav-btn {
                width: 100%;
                text-align: center;
            }

            .floating-tutor {
                width: 50px;
                height: 50px;
                font-size: 1.25rem;
                bottom: 1rem;
                right: 1rem;
            }

            .modal-content {
                width: 95%;
            }
        }

        @media (max-width: 480px) {
            .logo-text {
                display: none;
            }

            .lesson-map a {
                padding: 0.5rem 0.75rem;
                font-size: 0.75rem;
            }

            .section-header h2 {
                font-size: 1.1rem;
            }

            .theory-content h3 {
                font-size: 1.1rem;
            }

            .quiz-question h4 {
                font-size: 1rem;
            }
        }
    

/* From less1.html */

        /* ========================================
           CSS VARIABLES - Theme Configuration
           ======================================== */
        :root {
            --navy-dark: #0a1628;
            --navy: #1a2744;
            --navy-light: #2a3a5a;
            --teal: #00d4aa;
            --teal-light: #00f5c4;
            --teal-dark: #00b894;
            --white: #ffffff;
            --gray-50: #f8fafc;
            --gray-100: #f1f5f9;
            --gray-200: #e2e8f0;
            --gray-300: #cbd5e1;
            --gray-400: #94a3b8;
            --gray-500: #64748b;
            --gray-600: #475569;
            --gray-700: #334155;
            --success: #10b981;
            --success-light: #d1fae5;
            --error: #ef4444;
            --error-light: #fee2e2;
            --shadow-sm: 0 2px 8px rgba(10, 22, 40, 0.08);
            --shadow-md: 0 4px 16px rgba(10, 22, 40, 0.12);
            --shadow-lg: 0 8px 32px rgba(10, 22, 40, 0.16);
            --shadow-neu: 8px 8px 16px rgba(10, 22, 40, 0.1), -8px -8px 16px rgba(255, 255, 255, 0.9);
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-xl: 24px;
            --transition-fast: 0.15s ease;
            --transition-normal: 0.3s ease;
        }

        /* ========================================
           BASE STYLES & RESET
           ======================================== */
        *, *::before, *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        html {
            scroll-behavior: smooth;
            scroll-padding-top: 140px;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--gray-100);
            color: var(--gray-700);
            line-height: 1.6;
            overflow-x: hidden;
        }

        /* ========================================
           HEADER STYLES
           ======================================== */
        
        header {
            position: sticky;
            top: 0;
            z-index: 1000;
            background: var(--white);
            box-shadow: var(--shadow);
            padding: 1rem 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 12px;
            text-decoration: none;
        }

        .logo img {
            height: 45px;
            width: auto;
            border-radius: var(--radius-sm);
            transition: transform var(--transition-fast);
        }

        .logo:hover img {
            transform: scale(1.05);
        }

        header nav {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        header nav span {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-weight: 700;
            color: var(--navy);
        }

        header nav img {
            height: 28px;
            width: auto;
        }

        /* ========================================
           STICKY LESSON MAP NAVIGATION
           ======================================== */
        .sticky-nav {
            position: fixed;
            top: 70px;
            left: 0;
            right: 0;
            background: var(--navy);
            z-index: 999;
            padding: 0.75rem 1rem;
            box-shadow: var(--shadow-md);
        }

        .lesson-map {
            display: flex;
            flex-wrap: wrap;
            gap: 0.5rem;
            justify-content: center;
            list-style: none;
            max-width: 1200px;
            margin: 0 auto;
        }

        .lesson-map li {
            flex-shrink: 0;
        }

        .nav-link {
            display: inline-block;
            padding: 0.5rem 1rem;
            color: var(--gray-300);
            text-decoration: none;
            font-size: 0.85rem;
            font-weight: 500;
            border-radius: var(--radius-md);
            transition: all var(--transition-fast);
            white-space: nowrap;
        }

        .nav-link:hover, .nav-link.active {
            color: var(--white);
            background: var(--navy-light);
        }

        /* ========================================
           MAIN CONTENT AREA
           ======================================== */
        main {
            margin-top: 130px;
            padding: 1.5rem;
            max-width: 1000px;
            margin-left: auto;
            margin-right: auto;
            padding-bottom: 100px;
        }

        section {
            background: var(--white);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-neu);
            margin-bottom: 1.5rem;
            overflow: hidden;
        }

        /* ========================================
           COLLAPSIBLE SECTION HEADERS
           ======================================== */
        .section-header {
            background: linear-gradient(135deg, var(--navy), var(--navy-light));
            padding: 1rem 1.5rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
            user-select: none;
            transition: background var(--transition-fast);
        }

        .section-header:hover {
            background: linear-gradient(135deg, var(--navy-light), var(--navy));
        }

        .section-header h2 {
            color: var(--white);
            font-size: 1.15rem;
            font-weight: 700;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .toggle-icon {
            color: var(--teal);
            font-size: 1rem;
            transition: transform var(--transition-normal);
        }

        .section-header.collapsed .toggle-icon {
            transform: rotate(-90deg);
        }

        .section-content {
            padding: 1.5rem;
            max-height: 5000px;
            overflow: hidden;
            transition: max-height 0.4s ease, padding 0.3s ease, opacity 0.3s ease;
            opacity: 1;
        }

        .section-content.collapsed {
            max-height: 0;
            padding-top: 0;
            padding-bottom: 0;
            opacity: 0;
        }

        /* ========================================
           OBJECTIVES SECTION
           ======================================== */
