            background: var(--white);
            border-radius: var(--radius-md);
            box-shadow: var(--shadow-sm);
            align-items: flex-start;
        }

        .step-list li::before {
            content: counter(steps);
            min-width: 28px;
            height: 28px;
            background: var(--teal);
            color: var(--navy);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 0.85rem;
            flex-shrink: 0;
        }

        .practice-problems {
            background: var(--gray-100);
            border-radius: var(--radius-md);
            padding: 1.25rem;
            margin-top: 1.5rem;
        }

        .practice-problems h4 {
            color: var(--navy);
            margin-bottom: 1rem;
        }

        .practice-problems p {
            padding: 0.5rem 0;
            border-bottom: 1px dashed var(--gray-300);
        }

        .practice-problems p:last-child {
            border-bottom: none;
        }

        /* ========================================
           VIRTUAL LAB SECTION
           ======================================== */
        .lab-zone {
            background: var(--navy);
            border-radius: var(--radius-md);
            padding: 2rem;
            text-align: center;
            min-height: 350px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 1.5rem;
        }

        .lab-canvas {
            width: 100%;
            max-width: 600px;
            height: 200px;
            background: var(--navy-light);
            border-radius: var(--radius-md);
            border: 2px dashed var(--gray-500);
        }

        .sequence-display {
            display: flex;
            flex-wrap: wrap;
            gap: 0.75rem;
            justify-content: center;
        }

        .sequence-term {
            width: 55px;
            height: 55px;
            background: var(--teal);
            color: var(--navy);
            border-radius: var(--radius-md);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.15rem;
            font-weight: 700;
            opacity: 0;
            transform: scale(0);
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .sequence-term.visible {
            opacity: 1;
            transform: scale(1);
        }

        .sequence-formula {
            font-size: 1.15rem;
            color: var(--white);
            font-family: 'Courier New', monospace;
            background: var(--navy-light);
            padding: 0.75rem 1.5rem;
            border-radius: var(--radius-md);
        }

        .lab-controls {
            display: flex;
            gap: 1rem;
            flex-wrap: wrap;
            justify-content: center;
        }

        /* ========================================
           QUIZ SECTION STYLES
           ======================================== */
        .quiz-container p {
            color: var(--gray-600);
            margin-bottom: 1.5rem;
        }

        .quiz-question {
            background: var(--gray-50);
            border-radius: var(--radius-md);
            padding: 1.5rem;
            margin-bottom: 1.5rem;
        }

        .quiz-question h4 {
            color: var(--navy);
            font-size: 1.05rem;
            margin-bottom: 1rem;
        }

        .quiz-options {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .quiz-option {
            padding: 1rem 1.25rem;
            background: var(--white);
            border: 2px solid var(--gray-200);
            border-radius: var(--radius-md);
            cursor: pointer;
            transition: all var(--transition-fast);
            font-size: 0.95rem;
        }

        .quiz-option:hover:not(.disabled) {
            border-color: var(--teal);
            background: rgba(0, 212, 170, 0.05);
        }

        .quiz-option.correct {
            border-color: var(--success);
            background: var(--success-light);
        }

        .quiz-option.incorrect {
            border-color: var(--error);
            background: var(--error-light);
        }

        .quiz-option.disabled {
            cursor: not-allowed;
            opacity: 0.7;
        }

        .quiz-feedback {
            margin-top: 1rem;
            padding: 1rem;
            border-radius: var(--radius-md);
            display: none;
            background: var(--gray-100);
            border-left: 4px solid var(--teal);
        }

        .quiz-feedback.show {
            display: block;
            animation: fadeIn 0.3s ease;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .quiz-reset {
            text-align: center;
            margin-top: 1.5rem;
        }

        /* ========================================
           VIDEO SECTION STYLES
           ======================================== */
        .video-container {
            position: relative;
            width: 100%;
            padding-bottom: 56.25%;
            background: var(--navy);
            border-radius: var(--radius-md);
            overflow: hidden;
            margin: 1rem 0;
        }

        .video-container iframe {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            border: none;
        }

        .video-placeholder {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            color: var(--gray-400);
            gap: 1rem;
        }

        .play-btn {
            width: 70px;
            height: 70px;
            background: var(--teal);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all var(--transition-normal);
            box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4);
            animation: pulse 2s infinite;
        }

        .play-btn:hover {
            transform: scale(1.1);
            background: var(--teal-light);
        }

        @keyframes pulse {
            0% { box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4); }
            70% { box-shadow: 0 0 0 20px rgba(0, 212, 170, 0); }
            100% { box-shadow: 0 0 0 0 rgba(0, 212, 170, 0); }
        }

        /* ========================================
           TUTOR CTA SECTION
           ======================================== */
        .tutor-cta {
            background: linear-gradient(135deg, var(--navy), var(--navy-light));
            border-radius: var(--radius-lg);
            padding: 2.5rem;
            text-align: center;
            color: var(--white);
            position: relative;
            overflow: hidden;
        }

        .tutor-cta::before {
            content: '';
            position: absolute;
            top: -50%;
            right: -50%;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle, rgba(0, 212, 170, 0.15) 0%, transparent 70%);
        }

        .tutor-cta h3 {
            font-size: 1.5rem;
            margin-bottom: 0.75rem;
            position: relative;
        }

        .tutor-cta p {
            color: var(--gray-300);
            position: relative;
        }

        .tutor-cta a {
            color: var(--teal-light);
        }

        /* ========================================
           BUTTONS
           ======================================== */
        .btn-primary {
            background: linear-gradient(135deg, var(--teal), var(--teal-dark));
            color: var(--navy);
            border: none;
            padding: 0.875rem 2rem;
            border-radius: var(--radius-xl);
            font-family: inherit;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
            box-shadow: var(--shadow-md);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-lg);
        }

        .btn-secondary {
            background: var(--white);
            color: var(--navy);
            border: 2px solid var(--gray-200);
            padding: 0.75rem 1.5rem;
            border-radius: var(--radius-xl);
            font-family: inherit;
            font-size: 0.9rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
        }

        .btn-secondary:hover {
            border-color: var(--teal);
            color: var(--teal-dark);
        }

        /* ========================================
           FLOATING TUTOR BUTTON
           ======================================== */
        .floating-tutor {
            position: fixed;
            bottom: 90px;
            right: 1.5rem;
            width: 60px;
            height: 60px;
            background: linear-gradient(135deg, var(--teal), var(--teal-dark));
            color: var(--navy);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.75rem;
            cursor: pointer;
            box-shadow: var(--shadow-lg);
            z-index: 998;
            transition: all var(--transition-fast);
        }

        .floating-tutor:hover {
            transform: scale(1.1);
            box-shadow: 0 8px 30px rgba(0, 212, 170, 0.4);
        }

        /* ========================================
           MODAL STYLES
           ======================================== */
        .modal {
            position: fixed;
            inset: 0;
            background: rgba(10, 22, 40, 0.8);
            backdrop-filter: blur(4px);
            z-index: 2000;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 1.5rem;
            opacity: 0;
            visibility: hidden;
            transition: all var(--transition-normal);
        }

        .modal.active {
            opacity: 1;
            visibility: visible;
        }

        .modal-content {
            background: var(--white);
            border-radius: var(--radius-lg);
            max-width: 450px;
            width: 100%;
            transform: scale(0.9) translateY(20px);
            transition: all var(--transition-normal);
            overflow: hidden;
        }

        .modal.active .modal-content {
            transform: scale(1) translateY(0);
        }

        .modal-header {
            background: linear-gradient(135deg, var(--navy), var(--navy-light));
            padding: 1.25rem 1.5rem;
            color: var(--white);
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .modal-header h2 {
            font-size: 1.15rem;
        }

        .close-btn {
            background: none;
            border: none;
            color: var(--gray-300);
            font-size: 1.75rem;
            cursor: pointer;
            line-height: 1;
            transition: color var(--transition-fast);
        }

        .close-btn:hover {
            color: var(--white);
        }

        .modal-content > p,
        .modal-content > form {
            padding: 0 1.5rem;
        }

        .modal-content > p {
            padding-top: 1.5rem;
        }

        .modal-content > form {
            padding-bottom: 1.5rem;
        }

        .modal-content input,
        .modal-content textarea {
            width: 100%;
            padding: 0.75rem;
            border: 2px solid var(--gray-200);
            border-radius: var(--radius-md);
            font-family: inherit;
            font-size: 0.95rem;
            transition: border-color var(--transition-fast);
        }

        .modal-content input:focus,
        .modal-content textarea:focus {
            outline: none;
            border-color: var(--teal);
        }

        /* ========================================
           FOOTER NAVIGATION
           ======================================== */
        .lesson-nav {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background: var(--white);
            box-shadow: 0 -4px 16px rgba(10, 22, 40, 0.1);
            padding: 0.75rem 1.5rem;
            z-index: 997;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .nav-btn {
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            padding: 0.625rem 1.25rem;
            border-radius: var(--radius-md);
            font-family: inherit;
            font-size: 0.9rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
            text-decoration: none;
            background: var(--gray-100);
            color: var(--gray-600);
            border: none;
        }

        .nav-btn:hover {
            background: var(--gray-200);
            color: var(--navy);
        }

        .nav-btn.primary {
            background: linear-gradient(135deg, var(--teal), var(--teal-dark));
            color: var(--navy);
            box-shadow: var(--shadow-sm);
        }

        .nav-btn.primary:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-md);
        }

        .nav-center {
            display: flex;
        }

        /* ========================================
           DIFFERENCE TABLE STYLES
           ======================================== */
        .difference-table {
            width: 100%;
            border-collapse: collapse;
            margin: 1rem 0;
            background: var(--white);
            border-radius: var(--radius-md);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
        }

        .difference-table th {
            background: var(--navy);
            color: var(--white);
            padding: 0.75rem;
            text-align: center;
            font-weight: 600;
        }

        .difference-table td {
            padding: 0.75rem;
            border: 1px solid var(--gray-200);
            text-align: center;
            font-family: 'Courier New', monospace;
        }

        .difference-table .highlight {
            background: var(--teal-light);
            color: var(--navy);
            font-weight: 600;
        }


        /* ========================================
           RESPONSIVE STYLES
           ======================================== */
        @media (max-width: 768px) {
            header {
                padding: 0 1rem;
                height: 60px;
            }

            header nav span {
                font-size: 1.1rem !important;
            }

            .sticky-nav {
                top: 60px;
                padding: 0.5rem;
            }

            .lesson-map {
                gap: 0.25rem;
            }

            .nav-link {
                padding: 0.4rem 0.6rem;
                font-size: 0.75rem;
            }

            main {
                margin-top: 115px;
                padding: 1rem;
            }

            .section-header {
                padding: 0.875rem 1rem;
            }

            .section-header h2 {
                font-size: 1rem;
            }

            .section-content {
                padding: 1rem;
            }

            .formula-box {
                font-size: 0.95rem;
                padding: 1rem;
            }

            .worked-example {
                padding: 1rem;
            }

            .lab-zone {
                padding: 1.5rem;
                min-height: 280px;
            }

            .sequence-term {
                width: 45px;
                height: 45px;
                font-size: 1rem;
            }

            .tutor-cta {
                padding: 1.75rem;
            }

            .tutor-cta h3 {
                font-size: 1.25rem;
            }

            .floating-tutor {
                width: 50px;
                height: 50px;
                font-size: 1.5rem;
                bottom: 80px;
                right: 1rem;
            }

            .lesson-nav {
                padding: 0.5rem 1rem;
            }

            .nav-btn {
                padding: 0.5rem 0.875rem;
                font-size: 0.8rem;
            }

            .nav-center .nav-btn span {
                display: none;
            }

            .modal-content {
                margin: 1rem;
            }

            .difference-table {
                font-size: 0.85rem;
            }
        }

        @media (max-width: 480px) {
            header nav span {
                font-size: 0.95rem !important;
            }

            .logo img {
                height: 36px;
            }

            .nav-link {
                padding: 0.35rem 0.5rem;
                font-size: 0.7rem;
            }

            .step-list li {
                flex-direction: column;
                align-items: flex-start;
            }

            .nav-btn {
                padding: 0.5rem 0.75rem;
            }

            .difference-table {
                display: block;
                overflow-x: auto;
            }
        }
    

