/* From less17.html */

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --primary-blue: #1a73e8;
            --secondary-blue: #4285f4;
            --light-blue: #e8f0fe;
            --dark-blue: #0d47a1;
            --white: #ffffff;
            --gray-100: #f8f9fa;
            --gray-200: #e9ecef;
            --gray-300: #dee2e6;
            --gray-600: #6c757d;
            --gray-800: #343a40;
            --success: #28a745;
            --error: #dc3545;
            --warning: #ffc107;
            --purple: #6f42c1;
            --teal: #20c997;
            --orange: #fd7e14;
            --pink: #e83e8c;
            --indigo: #6610f2;
            --shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            --shadow-lg: 0 10px 25px rgba(0, 0, 0, 0.15);
            --radius: 12px;
            --transition: all 0.3s ease;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, var(--light-blue) 0%, var(--white) 100%);
            min-height: 100vh;
            line-height: 1.6;
            color: var(--gray-800);
        }

        /* Header & Navigation */
        header {
            background: linear-gradient(135deg, var(--primary-blue) 0%, var(--dark-blue) 100%);
            color: var(--white);
            padding: 1rem 2rem;
            position: sticky;
            top: 0;
            z-index: 1000;
            box-shadow: var(--shadow-lg);
        }

        .header-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 1rem;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .logo-icon {
            width: 40px;
            height: 40px;
            background: var(--white);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--primary-blue);
            font-weight: bold;
        }

        /* Dropdown Navigation */
        .nav-container {
            position: relative;
        }

        .nav-toggle {
            background: rgba(255, 255, 255, 0.2);
            border: 2px solid rgba(255, 255, 255, 0.3);
            color: var(--white);
            padding: 0.75rem 1.5rem;
            border-radius: 25px;
            cursor: pointer;
            font-size: 1rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
            transition: var(--transition);
        }

        .nav-toggle:hover {
            background: rgba(255, 255, 255, 0.3);
        }

        .nav-toggle::after {
            content: 'â–¼';
            font-size: 0.7rem;
            transition: var(--transition);
        }

        .nav-toggle.active::after {
            transform: rotate(180deg);
        }

        .dropdown-menu {
            position: absolute;
            top: 100%;
            right: 0;
            background: var(--white);
            border-radius: var(--radius);
            box-shadow: var(--shadow-lg);
            min-width: 300px;
            opacity: 0;
            visibility: hidden;
            transform: translateY(-10px);
            transition: var(--transition);
            margin-top: 0.5rem;
            overflow: hidden;
            max-height: 400px;
            overflow-y: auto;
        }

        .dropdown-menu.active {
            opacity: 1;
            visibility: visible;
            transform: translateY(0);
        }

        .dropdown-menu a {
            display: block;
            padding: 1rem 1.5rem;
            color: var(--gray-800);
            text-decoration: none;
            transition: var(--transition);
            border-bottom: 1px solid var(--gray-200);
        }

        .dropdown-menu a:last-child {
            border-bottom: none;
        }

        .dropdown-menu a:hover {
            background: var(--light-blue);
            color: var(--primary-blue);
            padding-left: 2rem;
        }

        .dropdown-menu a.current {
            background: var(--primary-blue);
            color: var(--white);
        }

        /* Main Content */
        main {
            max-width: 1100px;
            margin: 0 auto;
            padding: 2rem;
        }

        /* Cards */
        .card {
            background: var(--white);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            padding: 2rem;
            margin-bottom: 2rem;
            transition: var(--transition);
            animation: fadeInUp 0.6s ease;
        }

        .card:hover {
            box-shadow: var(--shadow-lg);
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* Subject & Grade Badge */
        .subject-badge {
            display: inline-flex;
            gap: 0.75rem;
            flex-wrap: wrap;
            margin-bottom: 1rem;
        }

        .badge {
            background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue));
            color: var(--white);
            padding: 0.5rem 1.25rem;
            border-radius: 25px;
            font-weight: 600;
            font-size: 0.85rem;
            box-shadow: var(--shadow);
        }

        .badge.outline {
            background: transparent;
            border: 2px solid var(--primary-blue);
            color: var(--primary-blue);
        }

        .badge.functions {
            background: linear-gradient(135deg, var(--indigo), var(--purple));
        }

        /* Topic Header */
        .topic-header {
            text-align: center;
            margin-bottom: 2rem;
        }

        .topic-header h1 {
            color: var(--dark-blue);
            font-size: 2.25rem;
            margin-bottom: 0.5rem;
        }

        .topic-header .subtitle {
            color: var(--gray-600);
            font-size: 1.2rem;
        }

        .lesson-number {
            display: inline-block;
            background: var(--indigo);
            color: var(--white);
            padding: 0.25rem 1rem;
            border-radius: 15px;
            font-weight: 600;
            margin-bottom: 1rem;
        }

        /* Section Headers */
        .section-header {
            display: flex;
            align-items: center;
            gap: 1rem;
            margin-bottom: 1.5rem;
            padding-bottom: 0.75rem;
            border-bottom: 3px solid var(--primary-blue);
        }

        .section-icon {
            width: 45px;
            height: 45px;
            background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue));
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--white);
            font-size: 1.25rem;
        }

        .section-header h2 {
            color: var(--dark-blue);
            font-size: 1.5rem;
        }

        /* Objectives List */
        .objectives-list {
            list-style: none;
        }

        .objectives-list li {
            padding: 0.75rem 1rem;
            margin-bottom: 0.5rem;
            background: var(--light-blue);
            border-radius: 8px;
            display: flex;
            align-items: center;
            gap: 0.75rem;
            transition: var(--transition);
        }

        .objectives-list li:hover {
            transform: translateX(5px);
            background: var(--gray-200);
        }

        .objectives-list li::before {
            content: 'âœ“';
            color: var(--success);
            font-weight: bold;
            font-size: 1.25rem;
        }

        /* Tabs */
        .tabs-container {
            margin: 1.5rem 0;
        }

        .tabs-header {
            display: flex;
            gap: 0.5rem;
            margin-bottom: 1.5rem;
            flex-wrap: wrap;
            border-bottom: 2px solid var(--gray-200);
            padding-bottom: 0.5rem;
        }

        .tab-btn {
            padding: 0.75rem 1.25rem;
            border: none;
            background: var(--gray-100);
            border-radius: 25px 25px 0 0;
            cursor: pointer;
            font-weight: 600;
            transition: var(--transition);
            font-size: 0.9rem;
        }

        .tab-btn:hover {
            background: var(--light-blue);
            color: var(--primary-blue);
        }

        .tab-btn.active {
            background: var(--primary-blue);
            color: var(--white);
        }

        .tab-btn.linear.active { background: var(--teal); }
        .tab-btn.quadratic.active { background: var(--purple); }
        .tab-btn.hyperbolic.active { background: var(--orange); }
        .tab-btn.exponential.active { background: var(--pink); }

        .tab-content {
            display: none;
            animation: fadeInUp 0.3s ease;
        }

        .tab-content.active {
            display: block;
        }

        /* Formula Box */
        .formula-box {
            background: linear-gradient(135deg, var(--dark-blue), var(--primary-blue));
            color: var(--white);
            padding: 1.5rem 2rem;
            border-radius: var(--radius);
            margin: 1.5rem 0;
            text-align: center;
            box-shadow: var(--shadow-lg);
        }

        .formula-box.linear { background: linear-gradient(135deg, var(--teal), #17a2b8); }
        .formula-box.quadratic { background: linear-gradient(135deg, var(--purple), #9b59b6); }
        .formula-box.hyperbolic { background: linear-gradient(135deg, var(--orange), #e67e22); }
        .formula-box.exponential { background: linear-gradient(135deg, var(--pink), #c2185b); }
        .formula-box.domain { background: linear-gradient(135deg, var(--indigo), var(--purple)); }

        .formula-box h3 {
            margin-bottom: 1rem;
            font-size: 1.1rem;
            opacity: 0.9;
        }

        .formula {
            font-size: 1.4rem;
            font-family: 'Times New Roman', serif;
            font-style: italic;
            background: rgba(255, 255, 255, 0.15);
            padding: 0.75rem 1.5rem;
            border-radius: 8px;
            display: inline-block;
            margin: 0.25rem;
        }

        /* Case Box */
        .case-box {
            background: var(--gray-100);
            border-radius: var(--radius);
            padding: 1.5rem;
            margin: 1rem 0;
            border-left: 5px solid var(--primary-blue);
        }

        .case-box.linear { border-left-color: var(--teal); }
        .case-box.quadratic { border-left-color: var(--purple); }
        .case-box.hyperbolic { border-left-color: var(--orange); }
        .case-box.exponential { border-left-color: var(--pink); }

        .case-box h4 {
            color: var(--dark-blue);
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .case-number {
            background: var(--primary-blue);
            color: var(--white);
            width: 28px;
            height: 28px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 0.85rem;
            font-weight: bold;
        }

        .case-box.linear .case-number { background: var(--teal); }
        .case-box.quadratic .case-number { background: var(--purple); }
        .case-box.hyperbolic .case-number { background: var(--orange); }
        .case-box.exponential .case-number { background: var(--pink); }

        .case-box ol, .case-box ul {
            margin-left: 1.5rem;
            margin-top: 0.5rem;
        }

        .case-box li {
            margin: 0.5rem 0;
        }

        /* Example Box */
        .example-box {
            background: var(--white);
            border: 2px solid var(--gray-200);
            padding: 1.5rem;
            border-radius: var(--radius);
            margin: 1rem 0;
        }

        .example-box h4 {
            color: var(--primary-blue);
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .example-box h4::before {
            content: 'ðŸ“';
        }

        .solution-steps {
            margin-top: 1rem;
        }

        .solution-steps .step {
            padding: 0.75rem;
            margin-bottom: 0.5rem;
            background: var(--gray-100);
            border-radius: 8px;
            display: flex;
            align-items: flex-start;
            gap: 1rem;
        }

        .step-number {
            width: 28px;
            height: 28px;
            background: var(--primary-blue);
            color: var(--white);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-size: 0.85rem;
            flex-shrink: 0;
        }

        .highlight {
            background: var(--warning);
            padding: 0.2rem 0.5rem;
            border-radius: 4px;
            font-weight: 600;
        }

        .final-answer {
            background: linear-gradient(135deg, var(--success), var(--teal));
            color: var(--white);
            padding: 1rem;
            border-radius: 8px;
            text-align: center;
            font-size: 1.1rem;
            font-weight: 600;
            margin-top: 1rem;
        }

        /* Note Box */
        .note-box {
            background: linear-gradient(135deg, #fff3cd, #ffeeba);
            border: 1px solid var(--warning);
            padding: 1.25rem;
            border-radius: var(--radius);
            margin: 1.5rem 0;
        }

        .note-box h4 {
            color: #856404;
            margin-bottom: 0.75rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .note-box h4::before {
            content: 'ðŸ’¡';
        }

        /* Definition Box */
        .definition-box {
            background: linear-gradient(135deg, #d1ecf1, #bee5eb);
            border: 1px solid #17a2b8;
            padding: 1.25rem;
            border-radius: var(--radius);
            margin: 1rem 0;
        }

        .definition-box h4 {
            color: #0c5460;
            margin-bottom: 0.75rem;
        }

        .definition-box p {
            color: #0c5460;
        }

        /* Comparison Table */
        .comparison-table {
            width: 100%;
            border-collapse: collapse;
            margin: 1.5rem 0;
            border-radius: var(--radius);
            overflow: hidden;
            box-shadow: var(--shadow);
        }

        .comparison-table th,
        .comparison-table td {
            padding: 1rem;
            text-align: left;
            border: 1px solid var(--gray-200);
        }

        .comparison-table thead th {
            background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue));
            color: var(--white);
            font-weight: 600;
        }

        .comparison-table tbody tr:nth-child(even) {
            background: var(--gray-100);
        }

        .comparison-table tbody tr:hover {
            background: var(--light-blue);
        }

        /* Simulation Container */
        .simulation-container {
            background: var(--white);
            border: 2px solid var(--primary-blue);
            border-radius: var(--radius);
            padding: 1.5rem;
            margin: 1.5rem 0;
        }

        .simulation-title {
            text-align: center;
            color: var(--dark-blue);
            margin-bottom: 1rem;
            font-size: 1.2rem;
        }

        .simulation-controls {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;
            justify-content: center;
            margin-bottom: 1rem;
            padding: 1rem;
            background: var(--gray-100);
            border-radius: 8px;
        }

        .control-group {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.25rem;
        }

        .control-group label {
            font-size: 0.85rem;
            color: var(--gray-600);
            font-weight: 500;
        }

        .sim-input {
            padding: 0.5rem;
            border: 2px solid var(--gray-300);
            border-radius: 8px;
            font-size: 1rem;
            width: 100px;
            text-align: center;
            transition: var(--transition);
        }

        .sim-input:focus {
            outline: none;
            border-color: var(--primary-blue);
            box-shadow: 0 0 0 3px rgba(26, 115, 232, 0.2);
        }

        .sim-btn {
            background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue));
            color: var(--white);
            border: none;
            padding: 0.75rem 1.5rem;
            border-radius: 25px;
            font-size: 1rem;
            cursor: pointer;
            transition: var(--transition);
            font-weight: 600;
            box-shadow: var(--shadow);
        }

        .sim-btn:hover {
            transform: scale(1.05);
            box-shadow: var(--shadow-lg);
        }

        .canvas-container {
            display: flex;
            justify-content: center;
            overflow-x: auto;
        }

        canvas {
            border: 1px solid var(--gray-300);
            border-radius: 8px;
            background: var(--white);
            max-width: 100%;
        }

        .result-display {
            background: var(--gray-100);
            border-radius: 8px;
            padding: 1rem;
            margin-top: 1rem;
            text-align: center;
        }

        .result-display .equation {
            font-size: 1.25rem;
            font-family: 'Times New Roman', serif;
            font-style: italic;
            color: var(--dark-blue);
            font-weight: 600;
        }

        /* Quiz Section */
        .quiz-section {
            background: var(--white);
            border-radius: var(--radius);
            box-shadow: var(--shadow-lg);
            padding: 2rem;
            margin: 2rem 0;
        }

        .quiz-header {
            text-align: center;
            margin-bottom: 2rem;
        }

        .quiz-header h2 {
            color: var(--dark-blue);
            font-size: 1.75rem;
        }

        .quiz-progress {
            background: var(--gray-200);
            height: 8px;
            border-radius: 4px;
            margin-top: 1rem;
            overflow: hidden;
        }

        .quiz-progress-bar {
            height: 100%;
            background: linear-gradient(90deg, var(--primary-blue), var(--secondary-blue));
            border-radius: 4px;
            transition: width 0.5s ease;
            width: 0%;
        }

        .question-card {
            background: var(--gray-100);
            border-radius: var(--radius);
            padding: 1.5rem;
            margin-bottom: 1.5rem;
            border-left: 5px solid var(--gray-600);
            transition: var(--transition);
        }

        .question-card.answered-correct {
            border-left-color: var(--success);
            background: #d4edda;
        }

        .question-card.answered-incorrect {
            border-left-color: var(--error);
            background: #f8d7da;
        }

        .question-number {
            display: inline-block;
            background: var(--primary-blue);
            color: var(--white);
            padding: 0.25rem 0.75rem;
            border-radius: 15px;
            font-size: 0.85rem;
            font-weight: 600;
            margin-bottom: 0.75rem;
        }

        .question-text {
            font-size: 1.05rem;
            margin-bottom: 1rem;
            color: var(--gray-800);
        }

        .options-list {
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
        }

        .option-label {
            display: flex;
            align-items: center;
            gap: 0.75rem;
            padding: 1rem;
            background: var(--white);
            border: 2px solid var(--gray-200);
            border-radius: 8px;
            cursor: pointer;
            transition: var(--transition);
        }

        .option-label:hover:not(.disabled) {
            border-color: var(--primary-blue);
            background: var(--light-blue);
        }

        .option-label.disabled {
            cursor: not-allowed;
            opacity: 0.8;
        }

        .option-label.selected {
            border-color: var(--primary-blue);
            background: var(--light-blue);
        }

        .option-label.correct {
            border-color: var(--success);
            background: #d4edda;
        }

        .option-label.incorrect {
            border-color: var(--error);
            background: #f8d7da;
        }

        .option-label input[type="radio"] {
            width: 20px;
            height: 20px;
            accent-color: var(--primary-blue);
        }

        .feedback {
            margin-top: 1rem;
            padding: 1rem;
            border-radius: 8px;
            display: none;
            animation: fadeInUp 0.3s ease;
        }

        .feedback.show {
            display: block;
        }

        .feedback.correct {
            background: #d4edda;
            color: #155724;
            border: 1px solid var(--success);
        }

        .feedback.incorrect {
            background: #f8d7da;
            color: #721c24;
            border: 1px solid var(--error);
        }

        /* Score Display */
        .score-display {
            background: linear-gradient(135deg, var(--dark-blue), var(--primary-blue));
            color: var(--white);
            padding: 2rem;
            border-radius: var(--radius);
            text-align: center;
            margin-top: 2rem;
            display: none;
        }

        .score-display.show {
            display: block;
            animation: fadeInUp 0.5s ease;
        }

        .score-circle {
            width: 150px;
            height: 150px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.2);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            margin: 0 auto 1rem;
            border: 4px solid var(--white);
        }

        .score-number {
            font-size: 3rem;
            font-weight: 700;
        }

        .score-label {
            font-size: 1rem;
            opacity: 0.9;
        }

        .score-message {
            font-size: 1.25rem;
            margin-top: 1rem;
        }

        .submit-quiz-btn {
            background: var(--white);
            color: var(--primary-blue);
            border: none;
            padding: 1rem 3rem;
            border-radius: 25px;
            font-size: 1.1rem;
            cursor: pointer;
            transition: var(--transition);
            font-weight: 600;
            box-shadow: var(--shadow);
            margin-top: 1.5rem;
        }

        .submit-quiz-btn:hover {
            transform: scale(1.05);
            box-shadow: var(--shadow-lg);
        }

        .retry-btn {
            background: var(--warning);
            color: var(--gray-800);
            border: none;
            padding: 0.75rem 2rem;
            border-radius: 25px;
            font-size: 1rem;
            cursor: pointer;
            transition: var(--transition);
            font-weight: 600;
            margin-top: 1rem;
        }

        .retry-btn:hover {
            transform: scale(1.05);
        }

        /* Navigation Buttons */
        .lesson-nav {
            display: flex;
            justify-content: space-between;
            gap: 1rem;
            margin: 2rem 0;
            flex-wrap: wrap;
        }

        .nav-btn {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            padding: 1rem 2rem;
            border-radius: 25px;
            font-size: 1rem;
            font-weight: 600;
            text-decoration: none;
            transition: var(--transition);
            cursor: pointer;
            border: none;
        }

        .nav-btn.prev {
            background: var(--white);
            color: var(--primary-blue);
            border: 2px solid var(--primary-blue);
        }

        .nav-btn.prev:hover {
            background: var(--light-blue);
            transform: translateX(-5px);
        }

        .nav-btn.next {
            background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue));
            color: var(--white);
            box-shadow: var(--shadow);
        }

        .nav-btn.next:hover {
            transform: translateX(5px);
            box-shadow: var(--shadow-lg);
        }

        /* Footer */
        footer {
            background: linear-gradient(135deg, var(--dark-blue), var(--primary-blue));
            color: var(--white);
            padding: 2rem;
            text-align: center;
            margin-top: 3rem;
        }

        footer p {
            opacity: 0.9;
        }

        /* Progress Indicator */
        .progress-indicator {
            position: fixed;
            bottom: 20px;
            right: 20px;
            background: var(--white);
            padding: 1rem;
            border-radius: var(--radius);
            box-shadow: var(--shadow-lg);
            z-index: 100;
            display: flex;
            align-items: center;
            gap: 0.75rem;
        }

        .progress-ring {
            width: 50px;
            height: 50px;
        }

        .progress-ring circle {
            fill: none;
            stroke-width: 4;
        }

        .progress-ring .bg {
            stroke: var(--gray-200);
        }

        .progress-ring .progress {
            stroke: var(--primary-blue);
            stroke-linecap: round;
            transform: rotate(-90deg);
            transform-origin: center;
            transition: stroke-dashoffset 0.5s ease;
        }

        /* Mobile Responsive */
        @media (max-width: 768px) {
            header {
                padding: 1rem;
            }

            .header-content {
                flex-direction: column;
                text-align: center;
            }

            .dropdown-menu {
                left: 50%;
                transform: translateX(-50%) translateY(-10px);
                width: 90vw;
                max-width: 300px;
            }

            .dropdown-menu.active {
                transform: translateX(-50%) translateY(0);
            }

            main {
                padding: 1rem;
            }

            .card {
                padding: 1.5rem;
            }

            .topic-header h1 {
                font-size: 1.75rem;
            }

            .formula {
                font-size: 1.1rem;
                padding: 0.5rem 0.75rem;
            }

            .tabs-header {
                justify-content: center;
            }

            .tab-btn {
                padding: 0.6rem 1rem;
                font-size: 0.8rem;
            }

            .simulation-controls {
                flex-direction: column;
                align-items: stretch;
            }

            .sim-input {
                width: 100%;
            }

            .lesson-nav {
                flex-direction: column;
            }

            .nav-btn {
                justify-content: center;
            }

            .progress-indicator {
                bottom: 10px;
                right: 10px;
                padding: 0.75rem;
            }

            .score-circle {
                width: 120px;
                height: 120px;
            }

            .score-number {
                font-size: 2.5rem;
            }

            .comparison-table {
                font-size: 0.85rem;
            }

            .comparison-table th,
            .comparison-table td {
                padding: 0.5rem;
            }
        }
    

/* From less18.html */

    /* ========================================
       CSS VARIABLES - Theme Configuration
       ======================================== */
    :root {
      --navy-dark: #0a1628;
      --navy: #1a2744;
      --navy-light: #2a3a5a;
      --teal: #00d4aa;
      --teal-light: #00f5c4;
      --teal-dark: #00b894;
      --white: #ffffff;
      --gray-50: #f8fafc;
      --gray-100: #f1f5f9;
      --gray-200: #e2e8f0;
      --gray-300: #cbd5e1;
      --gray-400: #94a3b8;
      --gray-500: #64748b;
      --gray-600: #475569;
      --gray-700: #334155;
      --success: #10b981;
      --success-light: #d1fae5;
      --error: #ef4444;
      --error-light: #fee2e2;
      --warning: #f59e0b;
      --warning-light: #fef3c7;
      --shadow-sm: 0 2px 8px rgba(10, 22, 40, 0.08);
      --shadow-md: 0 4px 16px rgba(10, 22, 40, 0.12);
      --shadow-lg: 0 8px 32px rgba(10, 22, 40, 0.16);
      --shadow-neu: 8px 8px 16px rgba(10, 22, 40, 0.1),
        -8px -8px 16px rgba(255, 255, 255, 0.9);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition-fast: 0.15s ease;
      --transition-normal: 0.3s ease;
    }

    /* ========================================
       BASE STYLES & RESET
       ======================================== */
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    html {
      scroll-behavior: smooth;
      scroll-padding-top: 140px;
    }
    body {
      font-family: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--gray-100);
      color: var(--gray-700);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ========================================
       HEADER STYLES
       ======================================== */
    header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: var(--white);
      box-shadow: var(--shadow-md);
      padding: 1rem 2rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 12px;
      text-decoration: none;
    }
    .logo img {
      height: 45px;
      width: auto;
      border-radius: var(--radius-sm);
      transition: transform var(--transition-fast);
    }
    .logo:hover img {
      transform: scale(1.05);
    }
    header nav {
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    header nav span {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-weight: 700;
      color: var(--navy);
    }
    header nav img {
      height: 28px;
      width: auto;
    }

    /* ========================================
       STICKY LESSON MAP NAVIGATION
       ======================================== */
    .sticky-nav {
      position: fixed;
      top: 70px;
      left: 0;
      right: 0;
      background: var(--navy);
      z-index: 999;
      padding: 0.75rem 1rem;
      box-shadow: var(--shadow-md);
    }
    .lesson-map {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      justify-content: center;
      list-style: none;
      max-width: 1200px;
      margin: 0 auto;
    }
    .lesson-map li {
      flex-shrink: 0;
    }
    .nav-link {
      display: inline-block;
      padding: 0.5rem 1rem;
      color: var(--gray-300);
      text-decoration: none;
      font-size: 0.85rem;
      font-weight: 500;
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
      white-space: nowrap;
    }
    .nav-link:hover,
    .nav-link.active {
      color: var(--white);
      background: var(--navy-light);
    }

    /* ========================================
       MAIN CONTENT AREA
       ======================================== */
    main {
      margin-top: 130px;
      padding: 1.5rem;
      max-width: 1000px;
      margin-left: auto;
      margin-right: auto;
      padding-bottom: 100px;
    }
    section {
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-neu);
      margin-bottom: 1.5rem;
      overflow: hidden;
    }

    /* ========================================
       COLLAPSIBLE SECTION HEADERS
       ======================================== */
    .section-header {
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
      padding: 1rem 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      cursor: pointer;
      user-select: none;
      transition: background var(--transition-fast);
    }
    .section-header:hover {
      background: linear-gradient(135deg, var(--navy-light), var(--navy));
    }
    .section-header h2 {
      color: var(--white);
      font-size: 1.15rem;
      font-weight: 700;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .toggle-icon {
      color: var(--teal);
      font-size: 1rem;
      transition: transform var(--transition-normal);
    }
    .section-header.collapsed .toggle-icon {
      transform: rotate(-90deg);
    }
    .section-content {
      padding: 1.5rem;
      max-height: 8000px;
      overflow: hidden;
      transition: max-height 0.5s ease, padding 0.3s ease, opacity 0.3s ease;
      opacity: 1;
    }
    .section-content.collapsed {
      max-height: 0;
      padding-top: 0;
      padding-bottom: 0;
      opacity: 0;
    }

    /* ========================================
       OBJECTIVES SECTION
       ======================================== */
    #objectives ul {
      list-style: none;
      margin-top: 1rem;
    }
    #objectives li {
      padding: 0.75rem 1rem;
      padding-left: 2.5rem;
      position: relative;
      background: var(--gray-50);
      border-radius: var(--radius-md);
      margin-bottom: 0.5rem;
      color: var(--gray-700);
      border-left: 4px solid var(--teal);
    }
    #objectives li::before {
      content: "âœ“";
      position: absolute;
      left: 1rem;
      color: var(--teal);
      font-weight: bold;
    }

    /* ========================================
       THEORY SECTION STYLES
       ======================================== */
    .theory-content h3 {
      color: var(--navy);
      font-size: 1.25rem;
      margin: 1.5rem 0 1rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
      padding-bottom: 0.5rem;
      border-bottom: 2px solid var(--gray-200);
    }
    .theory-content h3:first-child {
      margin-top: 0;
    }
    .theory-content p {
      margin-bottom: 1rem;
      color: var(--gray-600);
      line-height: 1.8;
    }
    .key-term {
      background: linear-gradient(
        135deg,
        rgba(0, 212, 170, 0.15),
        rgba(0, 212, 170, 0.05)
      );
      color: var(--teal-dark);
      padding: 0.125rem 0.5rem;
      border-radius: 4px;
      font-weight: 600;
      border-left: 3px solid var(--teal);
    }
    .formula-box {
      background: var(--navy);
      color: var(--white);
      padding: 1.25rem 1.5rem;
      border-radius: var(--radius-md);
      margin: 1.25rem 0;
      font-family: "Courier New", monospace;
      font-size: 1.1rem;
      text-align: center;
      box-shadow: var(--shadow-md);
    }
    .formula-box small {
      display: block;
      color: var(--gray-400);
      font-size: 0.85rem;
      margin-top: 0.5rem;
    }
    .worked-example {
      background: linear-gradient(135deg, var(--gray-50), var(--white));
      border-left: 4px solid var(--teal);
      padding: 1.25rem 1.5rem;
      border-radius: 0 var(--radius-md) var(--radius-md) 0;
      margin: 1.25rem 0;
    }
    .worked-example strong:first-child {
      display: block;
      color: var(--navy);
      font-size: 1.05rem;
      margin-bottom: 1rem;
      padding-bottom: 0.5rem;
      border-bottom: 1px dashed var(--gray-300);
    }
    .worked-example p {
      margin-bottom: 0.75rem;
    }
    .step-list {
      list-style: none;
      counter-reset: steps;
      margin: 1rem 0;
    }
    .step-list li {
      counter-increment: steps;
      display: flex;
      gap: 1rem;
      margin-bottom: 0.75rem;
      padding: 1rem;
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-sm);
      align-items: flex-start;
    }
    .step-list li::before {
      content: counter(steps);
      min-width: 28px;
      height: 28px;
      background: var(--teal);
      color: var(--navy);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 0.85rem;
      flex-shrink: 0;
    }

    /* ========================================
       GRAPH LAB SECTION
       ======================================== */
    .lab-zone {
      background: var(--navy);
      border-radius: var(--radius-md);
      padding: 2rem;
      text-align: center;
      min-height: 350px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-start;
      gap: 1.5rem;
    }
    .graph-canvas {
      width: 100%;
      max-width: 700px;
      background: var(--navy-light);
      border-radius: var(--radius-md);
      border: 2px solid var(--gray-500);
      padding: 1.5rem;
      color: white;
      font-family: monospace;
      font-size: 1rem;
      text-align: left;
    }
    .controls {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
      justify-content: center;
      margin-top: 1rem;
    }
    .btn-primary {
      background: linear-gradient(135deg, var(--teal), var(--teal-dark));
      color: var(--navy);
      border: none;
      padding: 0.875rem 2rem;
      border-radius: var(--radius-xl);
      font-family: inherit;
      font-size: 1rem;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition-fast);
      box-shadow: var(--shadow-md);
    }
    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-lg);
    }
    .btn-secondary {
      background: var(--white);
      color: var(--navy);
      border: 2px solid var(--gray-200);
      padding: 0.75rem 1.5rem;
      border-radius: var(--radius-xl);
      font-family: inherit;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition-fast);
    }
    .btn-secondary:hover {
      border-color: var(--teal);
      color: var(--teal-dark);
    }

    /* ========================================
       QUIZ, VIDEO, MODAL, FOOTER â€” (reuse original styles)
