    /* Include only minimal necessary duplicates to run standalone */
    .quiz-container p {
      color: var(--gray-600);
      margin-bottom: 1.5rem;
    }
    .quiz-question {
      background: var(--gray-50);
      border-radius: var(--radius-md);
      padding: 1.5rem;
      margin-bottom: 1.5rem;
    }
    .quiz-question h4 {
      color: var(--navy);
      font-size: 1.05rem;
      margin-bottom: 1rem;
    }
    .quiz-options {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }
    .quiz-option {
      padding: 1rem 1.25rem;
      background: var(--white);
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: all var(--transition-fast);
      font-size: 0.95rem;
    }
    .quiz-option:hover:not(.disabled) {
      border-color: var(--teal);
      background: rgba(0, 212, 170, 0.05);
    }
    .quiz-option.correct {
      border-color: var(--success);
      background: var(--success-light);
    }
    .quiz-option.incorrect {
      border-color: var(--error);
      background: var(--error-light);
    }
    .quiz-option.disabled {
      cursor: not-allowed;
      opacity: 0.7;
    }
    .quiz-feedback {
      margin-top: 1rem;
      padding: 1rem;
      border-radius: var(--radius-md);
      display: none;
      background: var(--gray-100);
      border-left: 4px solid var(--teal);
    }
    .quiz-feedback.show {
      display: block;
      animation: fadeIn 0.3s ease;
    }
    @keyframes fadeIn {
      from {
        opacity: 0;
        transform: translateY(-10px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }
    .video-container {
      position: relative;
      width: 100%;
      padding-bottom: 56.25%;
      background: var(--navy);
      border-radius: var(--radius-md);
      overflow: hidden;
      margin: 1rem 0;
    }
    .video-container iframe {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      border: none;
    }
    .video-placeholder {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      gap: 1rem;
    }
    .play-btn {
      width: 70px;
      height: 70px;
      background: var(--teal);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all var(--transition-normal);
      box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4);
      animation: pulse 2s infinite;
    }
    .play-btn:hover {
      transform: scale(1.1);
      background: var(--teal-light);
    }
    @keyframes pulse {
      0% {
        box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4);
      }
      70% {
        box-shadow: 0 0 0 20px rgba(0, 212, 170, 0);
      }
      100% {
        box-shadow: 0 0 0 0 rgba(0, 212, 170, 0);
      }
    }
    .tutor-cta {
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
      border-radius: var(--radius-lg);
      padding: 2.5rem;
      text-align: center;
      color: var(--white);
      position: relative;
      overflow: hidden;
    }
    .tutor-cta::before {
      content: "";
      position: absolute;
      top: -50%;
      right: -50%;
      width: 100%;
      height: 100%;
      background: radial-gradient(
        circle,
        rgba(0, 212, 170, 0.15) 0%,
        transparent 70%
      );
    }
    .tutor-cta h3 {
      font-size: 1.5rem;
      margin-bottom: 0.75rem;
      position: relative;
    }
    .tutor-cta p {
      color: var(--gray-300);
      position: relative;
    }
    .tutor-cta a {
      color: var(--teal-light);
    }

    .floating-tutor {
      position: fixed;
      bottom: 90px;
      right: 1.5rem;
      width: 60px;
      height: 60px;
      background: linear-gradient(135deg, var(--teal), var(--teal-dark));
      color: var(--navy);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.75rem;
      cursor: pointer;
      box-shadow: var(--shadow-lg);
      z-index: 998;
      transition: all var(--transition-fast);
    }
    .floating-tutor:hover {
      transform: scale(1.1);
      box-shadow: 0 8px 30px rgba(0, 212, 170, 0.4);
    }

    .modal {
      position: fixed;
      inset: 0;
      background: rgba(10, 22, 40, 0.8);
      backdrop-filter: blur(4px);
      z-index: 2000;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-normal);
    }
    .modal.active {
      opacity: 1;
      visibility: visible;
    }
    .modal-content {
      background: var(--white);
      border-radius: var(--radius-lg);
      max-width: 450px;
      width: 100%;
      transform: scale(0.9) translateY(20px);
      transition: all var(--transition-normal);
      overflow: hidden;
    }
    .modal.active .modal-content {
      transform: scale(1) translateY(0);
    }
    .modal-header {
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
