      transition: transform var(--transition-fast);
    }
    .logo:hover img {
      transform: scale(1.05);
    }
    header nav {
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    header nav span {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-weight: 700;
      color: var(--navy);
    }
    header nav img {
      height: 28px;
      width: auto;
    }

    /* STICKY NAV */
    .sticky-nav {
      position: fixed;
      top: 70px;
      left: 0;
      right: 0;
      background: var(--navy);
      z-index: 999;
      padding: 0.75rem 1rem;
      box-shadow: var(--shadow-md);
    }
    .lesson-map {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      justify-content: center;
      list-style: none;
      max-width: 1200px;
      margin: 0 auto;
    }
    .lesson-map li {
      flex-shrink: 0;
    }
    .nav-link {
      display: inline-block;
      padding: 0.5rem 1rem;
      color: var(--gray-300);
      text-decoration: none;
      font-size: 0.85rem;
      font-weight: 500;
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
      white-space: nowrap;
    }
    .nav-link:hover,
    .nav-link.active {
      color: var(--white);
      background: var(--navy-light);
    }

    /* MAIN CONTENT */
    main {
      margin-top: 130px;
      padding: 1.5rem;
      max-width: 1000px;
      margin-left: auto;
      margin-right: auto;
      padding-bottom: 100px;
    }
    section {
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-neu);
      margin-bottom: 1.5rem;
      overflow: hidden;
    }

    /* COLLAPSIBLE SECTIONS */
    .section-header {
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
      padding: 1rem 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      cursor: pointer;
      user-select: none;
      transition: background var(--transition-fast);
    }
    .section-header:hover {
      background: linear-gradient(135deg, var(--navy-light), var(--navy));
    }
    .section-header h2 {
      color: var(--white);
      font-size: 1.15rem;
      font-weight: 700;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .toggle-icon {
      color: var(--teal);
      font-size: 1rem;
      transition: transform var(--transition-normal);
    }
    .section-header.collapsed .toggle-icon {
      transform: rotate(-90deg);
    }
    .section-content {
      padding: 1.5rem;
      max-height: 8000px;
      overflow: hidden;
      transition: max-height 0.5s ease, padding 0.3s ease, opacity 0.3s ease;
      opacity: 1;
    }
    .section-content.collapsed {
      max-height: 0;
      padding-top: 0;
      padding-bottom: 0;
      opacity: 0;
    }

    /* OBJECTIVES */
    #objectives ul {
      list-style: none;
      margin-top: 1rem;
    }
    #objectives li {
      padding: 0.75rem 1rem;
      padding-left: 2.5rem;
      position: relative;
      background: var(--gray-50);
      border-radius: var(--radius-md);
      margin-bottom: 0.5rem;
      color: var(--gray-700);
      border-left: 4px solid var(--teal);
    }
    #objectives li::before {
      content: "âœ“";
      position: absolute;
      left: 1rem;
      color: var(--teal);
      font-weight: bold;
    }

    /* THEORY */
    .theory-content h3 {
      color: var(--navy);
      font-size: 1.25rem;
      margin: 1.5rem 0 1rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
      padding-bottom: 0.5rem;
      border-bottom: 2px solid var(--gray-200);
    }
    .theory-content p {
      margin-bottom: 1rem;
      color: var(--gray-600);
      line-height: 1.8;
    }
    .key-term {
      background: linear-gradient(
        135deg,
        rgba(0, 212, 170, 0.15),
        rgba(0, 212, 170, 0.05)
      );
      color: var(--teal-dark);
      padding: 0.125rem 0.5rem;
      border-radius: 4px;
      font-weight: 600;
      border-left: 3px solid var(--teal);
    }
    .formula-box {
      background: var(--navy);
      color: var(--white);
      padding: 1.25rem 1.5rem;
      border-radius: var(--radius-md);
      margin: 1.25rem 0;
      font-family: "Courier New", monospace;
      font-size: 1.1rem;
      text-align: center;
      box-shadow: var(--shadow-md);
    }
    .formula-box small {
      display: block;
      color: var(--gray-400);
      font-size: 0.85rem;
      margin-top: 0.5rem;
    }
    .worked-example {
      background: linear-gradient(135deg, var(--gray-50), var(--white));
      border-left: 4px solid var(--teal);
      padding: 1.25rem 1.5rem;
      border-radius: 0 var(--radius-md) var(--radius-md) 0;
      margin: 1.25rem 0;
    }
    .worked-example strong:first-child {
      display: block;
      color: var(--navy);
      font-size: 1.05rem;
      margin-bottom: 1rem;
      padding-bottom: 0.5rem;
      border-bottom: 1px dashed var(--gray-300);
    }
    .step-list {
      list-style: none;
      counter-reset: steps;
      margin: 1rem 0;
    }
    .step-list li {
      counter-increment: steps;
      display: flex;
      gap: 1rem;
      margin-bottom: 0.75rem;
      padding: 1rem;
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-sm);
      align-items: flex-start;
    }
    .step-list li::before {
      content: counter(steps);
      min-width: 28px;
      height: 28px;
      background: var(--teal);
      color: var(--navy);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 0.85rem;
      flex-shrink: 0;
    }
    .note-box {
      background: linear-gradient(135deg, rgba(0, 212, 170, 0.1), rgba(0, 212, 170, 0.05));
      border: 2px solid var(--teal);
      border-radius: var(--radius-md);
      padding: 1.25rem;
      margin: 1.25rem 0;
    }
    .note-box h4 {
      color: var(--teal-dark);
      margin-bottom: 0.5rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .warning-box {
      background: linear-gradient(135deg, rgba(239, 68, 68, 0.1), rgba(239, 68, 68, 0.05));
      border: 2px solid var(--error);
      border-radius: var(--radius-md);
      padding: 1.25rem;
      margin: 1.25rem 0;
    }
    .warning-box h4 {
      color: var(--error);
      margin-bottom: 0.5rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    /* LAB */
    .lab-zone {
      background: var(--navy);
      border-radius: var(--radius-md);
      padding: 2rem;
      text-align: center;
      min-height: 400px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-start;
      gap: 1.5rem;
    }
    .graph-canvas {
      width: 100%;
      max-width: 700px;
      background: var(--navy-light);
      border-radius: var(--radius-md);
      border: 2px solid var(--gray-500);
      padding: 1.5rem;
      color: white;
      font-family: monospace;
      font-size: 1rem;
      text-align: left;
    }
    .controls {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
      justify-content: center;
      margin-top: 1rem;
    }
    .btn-primary,
    .btn-secondary {
      padding: 0.75rem 1.5rem;
      border-radius: var(--radius-xl);
      font-family: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition-fast);
    }
    .btn-primary {
      background: linear-gradient(135deg, var(--teal), var(--teal-dark));
      color: var(--navy);
      border: none;
      box-shadow: var(--shadow-md);
    }
    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-lg);
    }
    .btn-secondary {
      background: var(--white);
      color: var(--navy);
      border: 2px solid var(--gray-200);
    }
    .btn-secondary:hover {
      border-color: var(--teal);
      color: var(--teal-dark);
    }

    /* QUIZ */
    .quiz-container p {
      color: var(--gray-600);
      margin-bottom: 1.5rem;
    }
    .quiz-question {
      background: var(--gray-50);
      border-radius: var(--radius-md);
      padding: 1.5rem;
      margin-bottom: 1.5rem;
    }
    .quiz-question h4 {
      color: var(--navy);
      font-size: 1.05rem;
      margin-bottom: 1rem;
    }
    .quiz-options {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }
    .quiz-option {
      padding: 1rem 1.25rem;
      background: var(--white);
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: all var(--transition-fast);
      font-size: 0.95rem;
    }
    .quiz-option:hover:not(.disabled) {
      border-color: var(--teal);
      background: rgba(0, 212, 170, 0.05);
    }
    .quiz-option.correct {
      border-color: var(--success);
      background: var(--success-light);
    }
    .quiz-option.incorrect {
      border-color: var(--error);
      background: var(--error-light);
    }
    .quiz-option.disabled {
      cursor: not-allowed;
      opacity: 0.7;
    }
    .quiz-feedback {
      margin-top: 1rem;
      padding: 1rem;
      border-radius: var(--radius-md);
      display: none;
      background: var(--gray-100);
      border-left: 4px solid var(--teal);
    }
    .quiz-feedback.show {
      display: block;
      animation: fadeIn 0.3s ease;
    }
    @keyframes fadeIn {
      from {
        opacity: 0;
        transform: translateY(-10px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    /* VIDEO */
    .video-container {
      position: relative;
      width: 100%;
      padding-bottom: 56.25%;
      background: var(--navy);
      border-radius: var(--radius-md);
      overflow: hidden;
      margin: 1rem 0;
    }
    .video-container iframe {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      border: none;
    }
    .video-placeholder {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      gap: 1rem;
    }
    .play-btn {
      width: 70px;
      height: 70px;
      background: var(--teal);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all var(--transition-normal);
      box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4);
      animation: pulse 2s infinite;
    }
    .play-btn:hover {
      transform: scale(1.1);
      background: var(--teal-light);
    }
    @keyframes pulse {
      0% {
        box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4);
      }
      70% {
        box-shadow: 0 0 0 20px rgba(0, 212, 170, 0);
      }
      100% {
        box-shadow: 0 0 0 0 rgba(0, 212, 170, 0);
      }
    }

    /* TUTOR CTA */
    .tutor-cta {
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
      border-radius: var(--radius-lg);
      padding: 2.5rem;
      text-align: center;
      color: var(--white);
      position: relative;
      overflow: hidden;
    }
    .tutor-cta::before {
      content: "";
      position: absolute;
      top: -50%;
      right: -50%;
      width: 100%;
      height: 100%;
      background: radial-gradient(
        circle,
        rgba(0, 212, 170, 0.15) 0%,
        transparent 70%
      );
    }
    .tutor-cta h3 {
      font-size: 1.5rem;
      margin-bottom: 0.75rem;
      position: relative;
    }
    .tutor-cta p {
      color: var(--gray-300);
      position: relative;
    }
    .tutor-cta a {
      color: var(--teal-light);
    }

    /* MODAL & FLOATING BUTTON */
    .floating-tutor {
      position: fixed;
      bottom: 90px;
      right: 1.5rem;
      width: 60px;
      height: 60px;
      background: linear-gradient(135deg, var(--teal), var(--teal-dark));
      color: var(--navy);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.75rem;
      cursor: pointer;
      box-shadow: var(--shadow-lg);
      z-index: 998;
      transition: all var(--transition-fast);
    }
    .floating-tutor:hover {
      transform: scale(1.1);
      box-shadow: 0 8px 30px rgba(0, 212, 170, 0.4);
    }

    .modal {
      position: fixed;
      inset: 0;
      background: rgba(10, 22, 40, 0.8);
      backdrop-filter: blur(4px);
      z-index: 2000;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-normal);
    }
    .modal.active {
      opacity: 1;
      visibility: visible;
    }
    .modal-content {
      background: var(--white);
      border-radius: var(--radius-lg);
      max-width: 450px;
      width: 100%;
      transform: scale(0.9) translateY(20px);
      transition: all var(--transition-normal);
      overflow: hidden;
    }
    .modal.active .modal-content {
      transform: scale(1) translateY(0);
    }
    .modal-header {
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
      padding: 1.25rem 1.5rem;
      color: var(--white);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .modal-header h2 {
      font-size: 1.15rem;
    }
    .close-btn {
      background: none;
      border: none;
      color: var(--gray-300);
      font-size: 1.75rem;
      cursor: pointer;
      line-height: 1;
      transition: color var(--transition-fast);
    }
    .close-btn:hover {
      color: var(--white);
    }
    .modal-content input,
    .modal-content textarea {
      width: 100%;
      padding: 0.75rem;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      font-family: inherit;
      font-size: 0.95rem;
      transition: border-color var(--transition-fast);
    }
    .modal-content input:focus,
    .modal-content textarea:focus {
      outline: none;
      border-color: var(--teal);
    }

    /* NAV FOOTER */
    .lesson-nav {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--white);
      box-shadow: 0 -4px 16px rgba(10, 22, 40, 0.1);
      padding: 0.75rem 1.5rem;
      z-index: 997;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .nav-btn {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.625rem 1.25rem;
      border-radius: var(--radius-md);
      font-family: inherit;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition-fast);
      text-decoration: none;
      background: var(--gray-100);
      color: var(--gray-600);
      border: none;
    }
    .nav-btn:hover {
      background: var(--gray-200);
      color: var(--navy);
    }
    .nav-btn.primary {
      background: linear-gradient(135deg, var(--teal), var(--teal-dark));
      color: var(--navy);
      box-shadow: var(--shadow-sm);
    }
    .nav-btn.primary:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }
    .nav-center {
      display: flex;
    }

    /* RESPONSIVE */
    @media (max-width: 768px) {
      header {
        padding: 0 1rem;
        height: 60px;
      }
      .sticky-nav {
        top: 60px;
        padding: 0.5rem;
      }
      .nav-link {
        padding: 0.4rem 0.6rem;
        font-size: 0.75rem;
      }
      main {
        margin-top: 115px;
        padding: 1rem;
      }
      .floating-tutor {
        bottom: 80px;
        right: 1rem;
        width: 50px;
        height: 50px;
      }
      .lesson-nav {
        padding: 0.5rem 1rem;
        .nav-btn span { display: none; }
      }
    }
  

