    :root {
      --navy-dark: #0a1628;
      --navy: #1a2744;
      --navy-light: #2a3a5a;
      --teal: #00d4aa;
      --teal-light: #00f5c4;
      --teal-dark: #00b894;
      --white: #ffffff;
      --gray-50: #f8fafc;
      --gray-100: #f1f5f9;
      --gray-200: #e2e8f0;
      --gray-300: #cbd5e1;
      --gray-400: #94a3b8;
      --gray-500: #64748b;
      --gray-600: #475569;
      --gray-700: #334155;
      --success: #10b981;
      --success-light: #d1fae5;
      --error: #ef4444;
      --error-light: #fee2e2;
      --warning: #f59e0b;
