    }
    .step-list li::before {
        content: counter(steps);
        min-width: 28px;
        height: 28px;
        background: var(--teal);
        color: var(--navy);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 700;
        font-size: 0.85rem;
        flex-shrink: 0;
    }
    .definition-box {
        background: var(--gray-50);
        padding: 1.25rem;
        border-radius: var(--radius-md);
        margin: 1.5rem 0;
        border-left: 4px solid var(--teal-dark);
    }
    .definition-box h4 {
        color: var(--teal-dark);
        margin-bottom: 0.5rem;
        display: flex;
        gap: 0.5rem;
    }
    .note-box, .warning-box, .info-box {
        padding: 1.25rem;
        margin: 1.25rem 0;
        border-radius: var(--radius-md);
    }
    .note-box {
        background: linear-gradient(135deg, rgba(0, 212, 170, 0.1), rgba(0, 212, 170, 0.05));
        border: 2px solid var(--teal);
    }
    .note-box h4 {
        color: var(--teal-dark);
    }
    .warning-box {
        background: linear-gradient(135deg, rgba(239, 68, 68, 0.1), rgba(239, 68, 68, 0.05));
        border: 2px solid var(--error);
    }
    .warning-box h4 {
        color: var(--error);
    }
    .info-box {
        background: var(--gray-50);
        border: 2px solid #3b82f6;
    }
    .info-box h4 {
        color: #3b82f6;
    }

    .conversion-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
        margin: 1.5rem 0;
    }
    @media (max-width: 768px) {
        .conversion-grid {
            grid-template-columns: 1fr;
        }
    }
    .conversion-card {
        background: var(--white);
        padding: 1rem;
        border-radius: var(--radius-md);
        box-shadow: var(--shadow-sm);
        border: 1px solid var(--gray-200);
    }
    .conversion-card h5 {
        color: var(--navy);
        margin-bottom: 0.75rem;
        display: flex;
        align-items: center;
        gap: 0.5rem;
    }
    .conversion-card ul {
        list-style: none;
        padding-left: 1rem;
    }
    .conversion-card li {
        margin-bottom: 0.5rem;
        padding-left: 1.5rem;
        position: relative;
    }
    .conversion-card li::before {
        content: "â†’";
        position: absolute;
        left: 0;
        color: var(--teal);
    }
    .graph-illustration {
        text-align: center;
        margin: 1.5rem 0;
        padding: 1rem;
        background: var(--gray-50);
        border-radius: var(--radius-md);
    }
    .graph-illustration p {
        font-style: italic;
        color: var(--gray-600);
        margin-top: 0.5rem;
    }

    /* ========================================
       BUTTONS
       ======================================== */
    .btn-primary {
        background: linear-gradient(135deg, var(--teal), var(--teal-dark));
        color: var(--navy);
        border: none;
        padding: 0.875rem 2rem;
        border-radius: var(--radius-xl);
        font-family: inherit;
        font-size: 1rem;
        font-weight: 600;
        cursor: pointer;
        transition: all var(--transition-fast);
        box-shadow: var(--shadow-md);
    }
    .btn-primary:hover {
        transform: translateY(-2px);
        box-shadow: var(--shadow-lg);
    }
    .btn-secondary {
        background: var(--white);
        color: var(--navy);
        border: 2px solid var(--gray-200);
        padding: 0.75rem 1.5rem;
        border-radius: var(--radius-xl);
        font-family: inherit;
        font-size: 0.9rem;
        font-weight: 600;
        cursor: pointer;
        transition: all var(--transition-fast);
    }
    .btn-secondary:hover {
        border-color: var(--teal);
        color: var(--teal-dark);
    }

    /* ========================================
       FLOATING TUTOR BUTTON
       ======================================== */
    .floating-tutor {
        position: fixed;
        bottom: 90px;
        right: 1.5rem;
        width: 60px;
        height: 60px;
        background: linear-gradient(135deg, var(--teal), var(--teal-dark));
        color: var(--navy);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 1.75rem;
        cursor: pointer;
        box-shadow: var(--shadow-lg);
        z-index: 998;
        transition: all var(--transition-fast);
    }
    .floating-tutor:hover {
        transform: scale(1.1);
        box-shadow: 0 8px 30px rgba(0, 212, 170, 0.4);
    }

    /* ========================================
       MODAL STYLES
       ======================================== */
    .modal {
        position: fixed;
        inset: 0;
        background: rgba(10, 22, 40, 0.8);
        backdrop-filter: blur(4px);
        z-index: 2000;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 1.5rem;
        opacity: 0;
        visibility: hidden;
        transition: all var(--transition-normal);
    }
    .modal.active {
        opacity: 1;
        visibility: visible;
    }
    .modal-content {
        background: var(--white);
        border-radius: var(--radius-lg);
        max-width: 450px;
        width: 100%;
        transform: scale(0.9) translateY(20px);
        transition: all var(--transition-normal);
        overflow: hidden;
    }
    .modal.active .modal-content {
        transform: scale(1) translateY(0);
    }
    .modal-header {
        background: linear-gradient(135deg, var(--navy), var(--navy-light));
        padding: 1.25rem 1.5rem;
        color: var(--white);
        display: flex;
        align-items: center;
        justify-content: space-between;
    }
    .modal-header h2 {
        font-size: 1.15rem;
    }
    .close-btn {
        background: none;
        border: none;
        color: var(--gray-300);
        font-size: 1.75rem;
        cursor: pointer;
        line-height: 1;
        transition: color var(--transition-fast);
    }
    .close-btn:hover {
        color: var(--white);
    }
    .modal-content > p,
    .modal-content > form {
        padding: 0 1.5rem;
    }
    .modal-content > p {
        padding-top: 1.5rem;
    }
    .modal-content > form {
        padding-bottom: 1.5rem;
    }
    .modal-content input,
    .modal-content textarea {
        width: 100%;
        padding: 0.75rem;
        border: 2px solid var(--gray-200);
        border-radius: var(--radius-md);
        font-family: inherit;
        font-size: 0.95rem;
        transition: border-color var(--transition-fast);
    }
    .modal-content input:focus,
    .modal-content textarea:focus {
        outline: none;
        border-color: var(--teal);
    }

    /* ========================================
       LESSON NAV FOOTER
       ======================================== */
    .lesson-nav {
        position: fixed;
        bottom: 0;
        left: 0;
        right: 0;
        background: var(--white);
        box-shadow: 0 -4px 16px rgba(10, 22, 40, 0.1);
        padding: 0.75rem 1.5rem;
        z-index: 997;
        display: flex;
        align-items: center;
        justify-content: space-between;
    }
    .nav-btn {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.625rem 1.25rem;
        border-radius: var(--radius-md);
        font-family: inherit;
        font-size: 0.9rem;
        font-weight: 600;
        cursor: pointer;
        transition: all var(--transition-fast);
        text-decoration: none;
        background: var(--gray-100);
        color: var(--gray-600);
        border: none;
    }
    .nav-btn:hover {
        background: var(--gray-200);
        color: var(--navy);
    }
    .nav-btn.primary {
        background: linear-gradient(135deg, var(--teal), var(--teal-dark));
        color: var(--navy);
        box-shadow: var(--shadow-sm);
    }
    .nav-btn.primary:hover {
        transform: translateY(-2px);
        box-shadow: var(--shadow-md);
    }
    .nav-center {
        display: flex;
    }

    /* ========================================
       RESPONSIVE STYLES
       ======================================== */
    @media (max-width: 768px) {
        header {
            padding: 0 1rem;
            height: 60px;
        }
        .sticky-nav {
            top: 60px;
            padding: 0.5rem;
        }
        .nav-link {
            padding: 0.4rem 0.6rem;
            font-size: 0.75rem;
        }
        main {
            margin-top: 115px;
            padding: 1rem;
        }
        .section-header {
            padding: 0.875rem 1rem;
        }
        .section-header h2 {
            font-size: 1rem;
        }
        .section-content {
            padding: 1rem;
        }
        .formula-box {
            font-size: 0.95rem;
            padding: 1rem;
        }
        .worked-example {
            padding: 1rem;
        }
        .floating-tutor {
            width: 50px;
            height: 50px;
            font-size: 1.5rem;
            bottom: 80px;
            right: 1rem;
        }
        .lesson-nav {
            padding: 0.5rem 1rem;
        }
        .nav-btn {
            padding: 0.5rem 0.875rem;
            font-size: 0.8rem;
        }
        .nav-center .nav-btn span {
            display: none;
        }
        .modal-content {
            margin: 1rem;
        }
    }
    @media (max-width: 480px) {
        .logo img {
            height: 36px;
        }
        .step-list li {
            flex-direction: column;
            align-items: flex-start;
        }
        .nav-btn {
            padding: 0.5rem 0.75rem;
        }
    }



  

/* From less23.html */

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --primary-blue: #1a73e8;
            --dark-blue: #0d47a1;
            --light-blue: #e3f2fd;
            --accent-blue: #42a5f5;
            --white: #ffffff;
            --gray: #f5f5f5;
            --dark-gray: #333;
            --success: #4caf50;
            --error: #f44336;
            --shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            --shadow-hover: 0 8px 15px rgba(0, 0, 0, 0.15);
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: var(--gray);
            color: var(--dark-gray);
            line-height: 1.6;
        }

        /* Header & Navigation */
        header {
            background: linear-gradient(135deg, var(--primary-blue), var(--dark-blue));
            padding: 1rem 2rem;
            position: sticky;
            top: 0;
            z-index: 1000;
            box-shadow: var(--shadow);
        }

        .header-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            color: var(--white);
            font-size: 1.5rem;
            font-weight: bold;
            text-decoration: none;
        }

        .logo span {
            color: var(--accent-blue);
        }

        nav {
            position: relative;
        }

        .nav-toggle {
            display: none;
            background: none;
            border: none;
            color: var(--white);
            font-size: 1.5rem;
            cursor: pointer;
        }

        .nav-menu {
            display: flex;
            list-style: none;
            gap: 1rem;
        }

        .nav-item {
            position: relative;
        }

        .nav-link {
            color: var(--white);
            text-decoration: none;
            padding: 0.5rem 1rem;
            border-radius: 5px;
            transition: background 0.3s;
            display: block;
        }

        .nav-link:hover {
            background: rgba(255, 255, 255, 0.2);
        }

        .dropdown-content {
            display: none;
            position: absolute;
            top: 100%;
            left: 0;
            background: var(--white);
            min-width: 200px;
            border-radius: 8px;
            box-shadow: var(--shadow-hover);
            overflow: hidden;
            animation: fadeIn 0.3s;
        }

        .nav-item:hover .dropdown-content {
            display: block;
        }

        .dropdown-content a {
            color: var(--dark-gray);
            padding: 0.75rem 1rem;
            display: block;
            text-decoration: none;
            transition: background 0.3s;
        }

        .dropdown-content a:hover {
            background: var(--light-blue);
            color: var(--primary-blue);
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Main Content */
        main {
            max-width: 1000px;
            margin: 2rem auto;
            padding: 0 1rem;
        }

        .card {
            background: var(--white);
            border-radius: 12px;
            padding: 2rem;
            margin-bottom: 2rem;
            box-shadow: var(--shadow);
            transition: transform 0.3s, box-shadow 0.3s;
        }

        .card:hover {
            box-shadow: var(--shadow-hover);
        }

        /* Subject Badge */
        .subject-badge {
            display: inline-flex;
            gap: 1rem;
            flex-wrap: wrap;
        }

        .badge {
            background: var(--primary-blue);
            color: var(--white);
            padding: 0.5rem 1rem;
            border-radius: 20px;
            font-size: 0.9rem;
            font-weight: 500;
        }

        .badge.secondary {
            background: var(--accent-blue);
        }

        /* Headings */
        h1 {
            color: var(--dark-blue);
            font-size: 2rem;
            margin-bottom: 0.5rem;
        }

        h2 {
            color: var(--primary-blue);
            font-size: 1.5rem;
            margin-bottom: 1rem;
            padding-bottom: 0.5rem;
            border-bottom: 2px solid var(--light-blue);
        }

        h3 {
            color: var(--dark-blue);
            font-size: 1.25rem;
            margin: 1.5rem 0 1rem;
        }

        .topic-label {
            color: var(--accent-blue);
            font-size: 1.1rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 0.5rem;
        }

        .lesson-number {
            color: #666;
            font-size: 1rem;
            margin-bottom: 1rem;
        }

        /* Objectives */
        .objectives-list {
            list-style: none;
            padding: 0;
        }

        .objectives-list li {
            padding: 0.75rem 0 0.75rem 2.5rem;
            position: relative;
            border-bottom: 1px solid var(--light-blue);
        }

        .objectives-list li:last-child {
            border-bottom: none;
        }

        .objectives-list li::before {
            content: 'âœ“';
            position: absolute;
            left: 0;
            top: 0.75rem;
            width: 24px;
            height: 24px;
            background: var(--success);
            color: var(--white);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.8rem;
        }

        /* Math Formulas */
        .formula {
            background: var(--light-blue);
            padding: 1rem 1.5rem;
            border-radius: 8px;
            font-family: 'Cambria Math', 'Times New Roman', serif;
            font-size: 1.1rem;
            margin: 1rem 0;
            display: inline-block;
            border-left: 4px solid var(--primary-blue);
        }

        .formula-box {
            background: linear-gradient(135deg, var(--light-blue), #bbdefb);
            padding: 1.5rem;
            border-radius: 10px;
            margin: 1.5rem 0;
            text-align: center;
        }

        .formula-box .formula {
            font-size: 1.3rem;
            background: var(--white);
        }

        /* Example Box */
        .example-box {
            background: #fff3e0;
            border-left: 4px solid #ff9800;
            padding: 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .example-box h4 {
            color: #e65100;
            margin-bottom: 1rem;
        }

        .step {
            margin: 0.5rem 0;
            padding-left: 1.5rem;
            position: relative;
        }

        .step::before {
            content: 'â†’';
            position: absolute;
            left: 0;
            color: var(--primary-blue);
        }

        /* Definition Box */
        .definition-box {
            background: #e8f5e9;
            border-left: 4px solid var(--success);
            padding: 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .definition-box h4 {
            color: #2e7d32;
            margin-bottom: 0.5rem;
        }

        /* Note Box */
        .note-box {
            background: #fce4ec;
            border-left: 4px solid #e91e63;
            padding: 1rem 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .note-box strong {
            color: #c2185b;
        }

        /* Characteristic List */
        .characteristic-list {
            list-style: none;
            padding: 0;
        }

        .characteristic-list li {
            padding: 0.75rem 0 0.75rem 2rem;
            position: relative;
            border-left: 2px solid var(--primary-blue);
            margin-left: 1rem;
            margin-bottom: 0.5rem;
        }

        .characteristic-list li::before {
            content: 'â€¢';
            position: absolute;
            left: -0.7rem;
            color: var(--primary-blue);
            font-size: 1.5rem;
            line-height: 1;
        }

        /* Simulation Container */
        .simulation-container {
            background: linear-gradient(135deg, #1a1a2e, #16213e);
            border-radius: 12px;
            padding: 2rem;
            margin: 2rem 0;
            color: var(--white);
        }

        .simulation-container h3 {
            color: var(--white);
            text-align: center;
            margin-bottom: 1.5rem;
        }

        .graph-container {
            background: var(--white);
            border-radius: 8px;
            padding: 1rem;
            margin-bottom: 1.5rem;
        }

        #graphCanvas, #inverseCanvas, #transformCanvas {
            display: block;
            margin: 0 auto;
            max-width: 100%;
        }

        .controls {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;
            justify-content: center;
            margin-top: 1rem;
        }

        .control-group {
            background: rgba(255, 255, 255, 0.1);
            padding: 1rem;
            border-radius: 8px;
            text-align: center;
        }

        .control-group label {
            display: block;
            margin-bottom: 0.5rem;
            font-weight: 500;
        }

        .slider {
            width: 150px;
            accent-color: var(--accent-blue);
        }

        .btn {
            background: var(--primary-blue);
            color: var(--white);
            border: none;
            padding: 0.75rem 1.5rem;
            border-radius: 8px;
            cursor: pointer;
            font-size: 1rem;
            transition: all 0.3s;
        }

        .btn:hover {
            background: var(--dark-blue);
            transform: translateY(-2px);
        }

        .btn.secondary {
            background: var(--accent-blue);
        }

        .btn.success {
            background: var(--success);
        }

        /* Legend */
        .legend {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;
            justify-content: center;
            margin-top: 1rem;
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .legend-color {
            width: 20px;
            height: 4px;
            border-radius: 2px;
        }

        /* Quiz Section */
        .quiz-section {
            margin-top: 2rem;
        }

        .question-card {
            background: var(--white);
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1.5rem;
            box-shadow: var(--shadow);
            border-left: 4px solid var(--primary-blue);
        }

        .question-number {
            background: var(--primary-blue);
            color: var(--white);
            width: 30px;
            height: 30px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            margin-right: 0.5rem;
        }

        .question-text {
            font-size: 1.1rem;
            margin-bottom: 1rem;
            display: inline;
        }

        .options {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
            margin-top: 1rem;
        }

        .option {
            display: flex;
            align-items: center;
            padding: 1rem;
            background: var(--gray);
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s;
            border: 2px solid transparent;
        }

        .option:hover {
            background: var(--light-blue);
            border-color: var(--accent-blue);
        }

        .option.selected {
            background: var(--light-blue);
            border-color: var(--primary-blue);
        }

        .option.correct {
            background: #e8f5e9;
            border-color: var(--success);
        }

        .option.incorrect {
            background: #ffebee;
            border-color: var(--error);
        }

        .option input {
            margin-right: 1rem;
            transform: scale(1.2);
        }

        .feedback {
            margin-top: 1rem;
            padding: 1rem;
            border-radius: 8px;
            display: none;
        }

        .feedback.correct {
            background: #e8f5e9;
            color: #2e7d32;
            display: block;
        }

        .feedback.incorrect {
            background: #ffebee;
            color: #c62828;
            display: block;
        }

        /* Score Display */
        .score-display {
            background: linear-gradient(135deg, var(--primary-blue), var(--dark-blue));
            color: var(--white);
            padding: 2rem;
            border-radius: 12px;
            text-align: center;
            margin-top: 2rem;
            display: none;
        }

        .score-display.show {
            display: block;
            animation: slideUp 0.5s ease;
        }

        @keyframes slideUp {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .score-value {
            font-size: 3rem;
            font-weight: bold;
            margin: 1rem 0;
        }

        .score-message {
            font-size: 1.2rem;
            opacity: 0.9;
        }

        .progress-bar {
            background: rgba(255, 255, 255, 0.3);
            height: 10px;
            border-radius: 5px;
            margin-top: 1rem;
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            background: var(--white);
            border-radius: 5px;
            transition: width 1s ease;
        }

        /* Navigation Buttons */
        .nav-buttons {
            display: flex;
            justify-content: space-between;
            gap: 1rem;
            margin-top: 2rem;
            flex-wrap: wrap;
        }

        .nav-btn {
            flex: 1;
            min-width: 150px;
            padding: 1rem 2rem;
            border-radius: 10px;
            font-size: 1rem;
            font-weight: 600;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
            text-decoration: none;
        }

        .nav-btn.prev {
            background: var(--gray);
            color: var(--dark-gray);
            border: 2px solid #ddd;
        }

        .nav-btn.next {
            background: var(--primary-blue);
            color: var(--white);
            border: none;
