            transition: background 0.3s;
        }

        .dropdown-content a:hover {
            background: var(--light-blue);
            color: var(--primary-blue);
        }

        .dropdown-content a.current {
            background: var(--light-blue);
            border-left: 3px solid var(--primary-blue);
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Main Content */
        main {
            max-width: 1000px;
            margin: 2rem auto;
            padding: 0 1rem;
        }

        .card {
            background: var(--white);
            border-radius: 12px;
            padding: 2rem;
            margin-bottom: 2rem;
            box-shadow: var(--shadow);
            transition: transform 0.3s, box-shadow 0.3s;
        }

        .card:hover {
            box-shadow: var(--shadow-hover);
        }

        /* Subject Badge */
        .subject-badge {
            display: inline-flex;
            gap: 1rem;
            flex-wrap: wrap;
        }

        .badge {
            background: var(--primary-blue);
            color: var(--white);
            padding: 0.5rem 1rem;
            border-radius: 20px;
            font-size: 0.9rem;
            font-weight: 500;
        }

        .badge.secondary {
            background: var(--accent-blue);
        }

        .badge.purple {
            background: var(--purple);
        }

        .badge.teal {
            background: var(--teal);
        }

        .badge.amber {
            background: var(--amber);
            color: var(--dark-gray);
        }

        /* Headings */
        h1 {
            color: var(--dark-blue);
            font-size: 2rem;
            margin-bottom: 0.5rem;
        }

        h2 {
            color: var(--primary-blue);
            font-size: 1.5rem;
            margin-bottom: 1rem;
            padding-bottom: 0.5rem;
            border-bottom: 2px solid var(--light-blue);
        }

        h3 {
            color: var(--dark-blue);
            font-size: 1.25rem;
            margin: 1.5rem 0 1rem;
        }

        .topic-label {
            color: var(--accent-blue);
            font-size: 1.1rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 0.5rem;
        }

        .lesson-number {
            color: #666;
            font-size: 1rem;
            margin-bottom: 1rem;
        }

        /* Objectives */
        .objectives-list {
            list-style: none;
            padding: 0;
        }

        .objectives-list li {
            padding: 0.75rem 0 0.75rem 2.5rem;
            position: relative;
            border-bottom: 1px solid var(--light-blue);
        }

        .objectives-list li:last-child {
            border-bottom: none;
        }

        .objectives-list li::before {
            content: 'âœ“';
            position: absolute;
            left: 0;
            top: 0.75rem;
            width: 24px;
            height: 24px;
            background: var(--success);
            color: var(--white);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.8rem;
        }

        /* Math Formulas */
        .formula {
            background: var(--light-blue);
            padding: 1rem 1.5rem;
            border-radius: 8px;
            font-family: 'Cambria Math', 'Times New Roman', serif;
            font-size: 1.1rem;
            margin: 1rem 0;
            display: inline-block;
            border-left: 4px solid var(--primary-blue);
        }

        .formula-box {
            background: linear-gradient(135deg, var(--light-blue), #bbdefb);
            padding: 1.5rem;
            border-radius: 10px;
            margin: 1.5rem 0;
            text-align: center;
        }

        .formula-box .formula {
            font-size: 1.3rem;
            background: var(--white);
        }

        .formula-large {
            font-size: 1.5rem;
            padding: 1.5rem 2rem;
        }

        /* Definition Box */
        .definition-box {
            background: #e8f5e9;
            border-left: 4px solid var(--success);
            padding: 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .definition-box h4 {
            color: #2e7d32;
            margin-bottom: 0.5rem;
        }

        /* Example Box */
        .example-box {
            background: #fff3e0;
            border-left: 4px solid #ff9800;
            padding: 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .example-box h4 {
            color: #e65100;
            margin-bottom: 1rem;
        }

        .step {
            margin: 0.75rem 0;
            padding-left: 1.5rem;
            position: relative;
        }

        .step::before {
            content: 'â†’';
            position: absolute;
            left: 0;
            color: var(--primary-blue);
        }

        .step-number {
            background: var(--primary-blue);
            color: white;
            width: 24px;
            height: 24px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 0.8rem;
            margin-right: 0.5rem;
        }

        /* Note Box */
        .note-box {
            background: #fce4ec;
            border-left: 4px solid #e91e63;
            padding: 1rem 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .note-box strong {
            color: #c2185b;
        }

        /* Key Concept Box */
        .key-concept {
            background: linear-gradient(135deg, #e1f5fe, #b3e5fc);
            border: 2px solid var(--accent-blue);
            padding: 1.5rem;
            border-radius: 10px;
            margin: 1.5rem 0;
        }

        .key-concept h4 {
            color: var(--dark-blue);
            margin-bottom: 0.5rem;
        }

        /* Application Box */
        .application-box {
            background: linear-gradient(135deg, #f3e5f5, #e1bee7);
            border: 2px solid #9c27b0;
            padding: 1.5rem;
            border-radius: 10px;
            margin: 1.5rem 0;
        }

        .application-box h4 {
            color: #7b1fa2;
            margin-bottom: 0.5rem;
        }

        /* Real-World Icon */
        .real-world-tag {
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            background: linear-gradient(135deg, #4caf50, #8bc34a);
            color: white;
            padding: 0.3rem 0.8rem;
            border-radius: 15px;
            font-size: 0.85rem;
            margin-bottom: 1rem;
        }

        /* Tables */
        .data-table {
            width: 100%;
            border-collapse: collapse;
            margin: 1.5rem 0;
            background: var(--white);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: var(--shadow);
        }

        .data-table th {
            background: var(--primary-blue);
            color: var(--white);
            padding: 1rem;
            text-align: left;
        }

        .data-table td {
            padding: 0.75rem 1rem;
            border-bottom: 1px solid var(--light-blue);
        }

        .data-table tr:nth-child(even) {
            background: var(--gray);
        }

        .data-table tr:hover {
            background: var(--light-blue);
        }

        /* Simulation Container */
        .simulation-container {
            background: linear-gradient(135deg, #1a1a2e, #16213e);
            border-radius: 12px;
            padding: 2rem;
            margin: 2rem 0;
            color: var(--white);
        }

        .simulation-container h3 {
            color: var(--white);
            text-align: center;
            margin-bottom: 1.5rem;
        }

        .interactive-tool {
            background: rgba(255, 255, 255, 0.1);
            border-radius: 10px;
            padding: 1.5rem;
            margin: 1rem 0;
        }

        .tool-input {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;
            align-items: center;
            justify-content: center;
            margin: 1rem 0;
        }

        .input-group {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.3rem;
        }

        .input-group label {
            font-size: 0.9rem;
            opacity: 0.9;
        }

        .tool-input input, .tool-input select {
            width: 120px;
            padding: 0.6rem;
            border-radius: 5px;
            border: 2px solid var(--accent-blue);
            font-size: 1rem;
            text-align: center;
            background: var(--white);
        }

        .tool-input input:focus {
            outline: none;
            border-color: var(--success);
        }

        .btn {
            background: var(--primary-blue);
            color: var(--white);
            border: none;
            padding: 0.75rem 1.5rem;
            border-radius: 8px;
            cursor: pointer;
            font-size: 1rem;
            transition: all 0.3s;
            margin: 0.25rem;
        }

        .btn:hover {
            background: var(--dark-blue);
            transform: translateY(-2px);
        }

        .btn.secondary {
            background: var(--accent-blue);
        }

        .btn.success {
            background: var(--success);
        }

        .btn.warning {
            background: var(--warning);
            color: var(--dark-gray);
        }

        .btn.purple {
            background: var(--purple);
        }

        .result-display {
            background: var(--success);
            color: var(--white);
            padding: 1.5rem;
            border-radius: 8px;
            text-align: center;
            font-size: 1.1rem;
            margin-top: 1rem;
        }

        .result-display.error {
            background: var(--error);
        }

        .solution-steps {
            background: rgba(255, 255, 255, 0.05);
            border-radius: 8px;
            padding: 1rem;
            margin-top: 1rem;
            text-align: left;
        }

        .solution-step {
            padding: 0.5rem 0;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
            font-family: 'Cambria Math', serif;
        }

        .solution-step:last-child {
            border-bottom: none;
        }

        /* Calculator Display */
        .calc-display {
            background: #1a1a2e;
            border: 2px solid var(--accent-blue);
            border-radius: 8px;
            padding: 1rem;
            margin: 1rem 0;
            text-align: center;
        }

        .calc-result {
            font-size: 2rem;
            font-weight: bold;
            color: var(--success);
        }

        .calc-label {
            font-size: 0.9rem;
            opacity: 0.8;
            margin-top: 0.5rem;
        }

        /* Timeline Visual */
        .timeline {
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 1.5rem 0;
            padding: 1rem;
            background: rgba(255, 255, 255, 0.05);
            border-radius: 8px;
        }

        .timeline-point {
            text-align: center;
            padding: 0.5rem 1rem;
        }

        .timeline-arrow {
            font-size: 1.5rem;
            color: var(--accent-blue);
            padding: 0 0.5rem;
        }

        /* Controls */
        .controls {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;
            justify-content: center;
            margin-top: 1rem;
        }

        .control-group {
            background: rgba(255, 255, 255, 0.1);
            padding: 1rem;
            border-radius: 8px;
            text-align: center;
            min-width: 150px;
        }

        .control-group label {
            display: block;
            margin-bottom: 0.5rem;
            font-weight: 500;
        }

        /* Quiz Section */
        .quiz-section {
            margin-top: 2rem;
        }

        .question-card {
            background: var(--white);
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1.5rem;
            box-shadow: var(--shadow);
            border-left: 4px solid var(--primary-blue);
        }

        .question-number {
            background: var(--primary-blue);
            color: var(--white);
            width: 30px;
            height: 30px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            margin-right: 0.5rem;
        }

        .question-text {
            font-size: 1.1rem;
            margin-bottom: 1rem;
            display: inline;
        }

        .options {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
            margin-top: 1rem;
        }

        .option {
            display: flex;
            align-items: center;
            padding: 1rem;
            background: var(--gray);
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s;
            border: 2px solid transparent;
        }

        .option:hover {
            background: var(--light-blue);
            border-color: var(--accent-blue);
        }

        .option.selected {
            background: var(--light-blue);
            border-color: var(--primary-blue);
        }

        .option.correct {
            background: #e8f5e9;
            border-color: var(--success);
        }

        .option.incorrect {
            background: #ffebee;
            border-color: var(--error);
        }

        .option input {
            margin-right: 1rem;
            transform: scale(1.2);
        }

        .feedback {
            margin-top: 1rem;
            padding: 1rem;
            border-radius: 8px;
            display: none;
        }

        .feedback.correct {
            background: #e8f5e9;
            color: #2e7d32;
            display: block;
        }

        .feedback.incorrect {
            background: #ffebee;
            color: #c62828;
            display: block;
        }

        /* Score Display */
        .score-display {
            background: linear-gradient(135deg, var(--primary-blue), var(--dark-blue));
            color: var(--white);
            padding: 2rem;
            border-radius: 12px;
            text-align: center;
            margin-top: 2rem;
            display: none;
        }

        .score-display.show {
            display: block;
            animation: slideUp 0.5s ease;
        }

        @keyframes slideUp {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .score-value {
            font-size: 3rem;
            font-weight: bold;
            margin: 1rem 0;
        }

        .score-message {
            font-size: 1.2rem;
            opacity: 0.9;
        }

        .progress-bar {
            background: rgba(255, 255, 255, 0.3);
            height: 10px;
            border-radius: 5px;
            margin-top: 1rem;
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            background: var(--white);
            border-radius: 5px;
            transition: width 1s ease;
        }

        /* Navigation Buttons */
        .nav-buttons {
            display: flex;
            justify-content: space-between;
            gap: 1rem;
            margin-top: 2rem;
            flex-wrap: wrap;
        }

        .nav-btn {
            flex: 1;
            min-width: 150px;
            padding: 1rem 2rem;
            border-radius: 10px;
            font-size: 1rem;
            font-weight: 600;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
            text-decoration: none;
            cursor: pointer;
            transition: all 0.3s;
        }

        .nav-btn.prev {
            background: var(--gray);
            color: var(--dark-gray);
            border: 2px solid #ddd;
        }

        .nav-btn.next {
            background: var(--primary-blue);
            color: var(--white);
            border: none;
        }

        .nav-btn:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-hover);
        }

        /* Footer */
        footer {
            background: var(--dark-blue);
            color: var(--white);
            text-align: center;
            padding: 2rem;
            margin-top: 3rem;
        }

        footer p {
            opacity: 0.9;
        }

        /* Math Content Styling */
        .math {
            font-family: 'Cambria Math', 'Times New Roman', serif;
            font-style: italic;
        }

        sub, sup {
            font-size: 0.75em;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-toggle {
                display: block;
            }

            .nav-menu {
                display: none;
                position: absolute;
                top: 100%;
                right: 0;
                background: var(--dark-blue);
                flex-direction: column;
                padding: 1rem;
                border-radius: 8px;
                min-width: 200px;
                box-shadow: var(--shadow-hover);
            }

            .nav-menu.active {
                display: flex;
            }

            .dropdown-content {
                position: static;
                box-shadow: none;
                background: rgba(255, 255, 255, 0.1);
                margin-top: 0.5rem;
            }

            .dropdown-content a {
                color: var(--white);
            }

            h1 {
                font-size: 1.5rem;
            }

            .card {
                padding: 1.5rem;
            }

            .simulation-container {
                padding: 1rem;
            }

            .tool-input {
                flex-direction: column;
            }

            .tool-input input {
                width: 100%;
                max-width: 200px;
            }

            .timeline {
                flex-direction: column;
            }

            .timeline-arrow {
                transform: rotate(90deg);
            }
        }

        /* Utility */
        .text-center { text-align: center; }
        .mt-1 { margin-top: 1rem; }
        .mt-2 { margin-top: 2rem; }
        .mb-1 { margin-bottom: 1rem; }
        .mb-2 { margin-bottom: 2rem; }

        /* Info Cards Grid */
        .info-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 1rem;
            margin: 1.5rem 0;
        }

        .info-card {
            background: rgba(255, 255, 255, 0.1);
            padding: 1.5rem;
            border-radius: 10px;
            text-align: center;
        }

        .info-card h5 {
            color: var(--accent-blue);
            margin-bottom: 0.5rem;
        }

        .info-card .icon {
            font-size: 2rem;
            margin-bottom: 0.5rem;
        }

        /* Proof Box */
        .proof-box {
            background: #e8eaf6;
            border-left: 4px solid #3f51b5;
            padding: 1.5rem;
            border-radius: 0 10px 10px 0;
            margin: 1.5rem 0;
        }

        .proof-box h4 {
            color: #303f9f;
            margin-bottom: 0.5rem;
        }

        /* Verification Box */
        .verification-box {
            background: #e0f7fa;
            border: 2px dashed #00bcd4;
            padding: 1.5rem;
            border-radius: 10px;
            margin: 1.5rem 0;
        }
    

