/* From less8.html */

        /* ========================================
           CSS VARIABLES - Theme Configuration
           ======================================== */
        :root {
            --navy-dark: #0a1628;
            --navy: #1a2744;
            --navy-light: #2a3a5a;
            --teal: #00d4aa;
            --teal-light: #00f5c4;
            --teal-dark: #00b894;
            --gold: #ffb74d;
            --gold-light: #ffcc80;
            --gold-dark: #ff9800;
            --white: #ffffff;
            --gray-50: #f8fafc;
            --gray-100: #f1f5f9;
            --gray-200: #e2e8f0;
            --gray-300: #cbd5e1;
            --gray-400: #94a3b8;
            --gray-500: #64748b;
            --gray-600: #475569;
            --gray-700: #334155;
            --success: #10b981;
            --success-light: #d1fae5;
            --error: #ef4444;
            --error-light: #fee2e2;
            --shadow-sm: 0 2px 8px rgba(10, 22, 40, 0.08);
            --shadow-md: 0 4px 16px rgba(10, 22, 40, 0.12);
            --shadow-lg: 0 8px 32px rgba(10, 22, 40, 0.16);
            --shadow-neu: 8px 8px 16px rgba(10, 22, 40, 0.1), -8px -8px 16px rgba(255, 255, 255, 0.9);
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-xl: 24px;
            --transition-fast: 0.15s ease;
            --transition-normal: 0.3s ease;
        }

        /* ========================================
           BASE STYLES & RESET
           ======================================== */
        *, *::before, *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        html {
            scroll-behavior: smooth;
            scroll-padding-top: 140px;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--gray-100);
            color: var(--gray-700);
            line-height: 1.6;
            overflow-x: hidden;
        }

        /* ========================================
           HEADER STYLES
           ======================================== */
        
        header {
            position: sticky;
            top: 0;
            z-index: 1000;
            background: var(--white);
            box-shadow: var(--shadow);
            padding: 1rem 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 12px;
            text-decoration: none;
        }

        .logo img {
            height: 45px;
            width: auto;
            border-radius: var(--radius-sm);
            transition: transform var(--transition-fast);
        }

        .logo:hover img {
            transform: scale(1.05);
        }

        header nav {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        header nav span {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-weight: 700;
            color: var(--navy);
        }

        header nav img {
            height: 28px;
            width: auto;
        }

        /* ========================================
           STICKY LESSON MAP NAVIGATION
           ======================================== */
        .sticky-nav {
            position: fixed;
            top: 70px;
            left: 0;
            right: 0;
            background: var(--navy);
            z-index: 999;
            padding: 0.75rem 1rem;
            box-shadow: var(--shadow-md);
        }

        .lesson-map {
            display: flex;
            flex-wrap: wrap;
            gap: 0.5rem;
            justify-content: center;
            list-style: none;
            max-width: 1200px;
            margin: 0 auto;
        }

        .lesson-map li {
            flex-shrink: 0;
        }

        .nav-link {
            display: inline-block;
            padding: 0.5rem 1rem;
            color: var(--gray-300);
            text-decoration: none;
            font-size: 0.85rem;
            font-weight: 500;
            border-radius: var(--radius-md);
            transition: all var(--transition-fast);
            white-space: nowrap;
        }

        .nav-link:hover, .nav-link.active {
            color: var(--white);
            background: var(--navy-light);
        }

        /* ========================================
           MAIN CONTENT AREA
           ======================================== */
        main {
            margin-top: 130px;
            padding: 1.5rem;
            max-width: 1000px;
            margin-left: auto;
            margin-right: auto;
            padding-bottom: 100px;
        }

        section {
            background: var(--white);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-neu);
            margin-bottom: 1.5rem;
            overflow: hidden;
        }

        /* ========================================
           COLLAPSIBLE SECTION HEADERS
           ======================================== */
        .section-header {
            background: linear-gradient(135deg, var(--navy), var(--navy-light));
            padding: 1rem 1.5rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
            user-select: none;
            transition: background var(--transition-fast);
        }

        .section-header:hover {
            background: linear-gradient(135deg, var(--navy-light), var(--navy));
        }

        .section-header h2 {
            color: var(--white);
            font-size: 1.15rem;
            font-weight: 700;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .toggle-icon {
            color: var(--teal);
            font-size: 1rem;
            transition: transform var(--transition-normal);
        }

        .section-header.collapsed .toggle-icon {
            transform: rotate(-90deg);
        }

        .section-content {
            padding: 1.5rem;
            max-height: 5000px;
            overflow: hidden;
            transition: max-height 0.4s ease, padding 0.3s ease, opacity 0.3s ease;
            opacity: 1;
        }

        .section-content.collapsed {
            max-height: 0;
            padding-top: 0;
            padding-bottom: 0;
            opacity: 0;
        }

        /* ========================================
           OBJECTIVES SECTION
           ======================================== */
        #objectives ul {
            list-style: none;
            margin-top: 1rem;
        }

        #objectives li {
            padding: 0.75rem 1rem;
            padding-left: 2.5rem;
            position: relative;
            background: var(--gray-50);
            border-radius: var(--radius-md);
            margin-bottom: 0.5rem;
            color: var(--gray-700);
            border-left: 4px solid var(--teal);
        }

        #objectives li::before {
            content: 'âœ“';
            position: absolute;
            left: 1rem;
            color: var(--teal);
            font-weight: bold;
        }

        /* ========================================
           PRE-KNOWLEDGE & BASELINE SECTIONS
           ======================================== */
        .knowledge-list, .baseline-list {
            list-style: none;
            margin-top: 1rem;
        }

        .knowledge-list li, .baseline-list li {
            padding: 0.75rem 1rem;
            background: var(--gray-50);
            border-radius: var(--radius-md);
            margin-bottom: 0.5rem;
            display: flex;
            align-items: flex-start;
            gap: 0.75rem;
        }

        .knowledge-list li::before {
            content: 'ðŸ“Œ';
        }

        .baseline-list li::before {
            content: 'â“';
        }

        /* ========================================
           THEORY SECTION STYLES
           ======================================== */
        .theory-content h3 {
            color: var(--navy);
            font-size: 1.25rem;
            margin: 1.5rem 0 1rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
            padding-bottom: 0.5rem;
            border-bottom: 2px solid var(--gray-200);
        }

        .theory-content h3:first-child {
            margin-top: 0;
        }

        .theory-content p {
            margin-bottom: 1rem;
            color: var(--gray-600);
            line-height: 1.8;
        }

        .key-term {
            background: linear-gradient(135deg, rgba(0, 212, 170, 0.15), rgba(0, 212, 170, 0.05));
            color: var(--teal-dark);
            padding: 0.125rem 0.5rem;
            border-radius: 4px;
            font-weight: 600;
            border-left: 3px solid var(--teal);
        }

        .key-term.gold {
            background: linear-gradient(135deg, rgba(255, 183, 77, 0.15), rgba(255, 183, 77, 0.05));
            color: var(--gold-dark);
            border-left: 3px solid var(--gold);
        }

        .formula-box {
            background: var(--navy);
            color: var(--white);
            padding: 1.25rem 1.5rem;
            border-radius: var(--radius-md);
            margin: 1.25rem 0;
            font-family: 'Courier New', monospace;
            font-size: 1.1rem;
            text-align: center;
            box-shadow: var(--shadow-md);
        }

        .formula-box.gold {
            background: linear-gradient(135deg, #ff9800, #ffb74d);
            color: var(--navy);
        }

        .formula-box small {
            display: block;
            color: var(--gray-400);
            font-size: 0.85rem;
            margin-top: 0.5rem;
        }

        .formula-box.gold small {
            color: rgba(26, 39, 68, 0.8);
        }

        .worked-example {
            background: linear-gradient(135deg, var(--gray-50), var(--white));
            border-left: 4px solid var(--teal);
            padding: 1.25rem 1.5rem;
            border-radius: 0 var(--radius-md) var(--radius-md) 0;
            margin: 1.25rem 0;
        }

        .worked-example.gold {
            border-left: 4px solid var(--gold);
        }

        .worked-example strong:first-child {
            display: block;
            color: var(--navy);
            font-size: 1.05rem;
            margin-bottom: 1rem;
            padding-bottom: 0.5rem;
            border-bottom: 1px dashed var(--gray-300);
        }

        .worked-example p {
            margin-bottom: 0.75rem;
        }

        .step-list {
            list-style: none;
            counter-reset: steps;
            margin: 1rem 0;
        }

        .step-list li {
            counter-increment: steps;
            display: flex;
            gap: 1rem;
            margin-bottom: 0.75rem;
            padding: 1rem;
            background: var(--white);
            border-radius: var(--radius-md);
            box-shadow: var(--shadow-sm);
            align-items: flex-start;
        }

        .step-list li::before {
            content: counter(steps);
            min-width: 28px;
            height: 28px;
            background: var(--teal);
            color: var(--navy);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 0.85rem;
            flex-shrink: 0;
        }

        .step-list.gold li::before {
            background: var(--gold);
        }

        .practice-problems {
            background: var(--gray-100);
            border-radius: var(--radius-md);
            padding: 1.25rem;
            margin-top: 1.5rem;
        }

        .practice-problems h4 {
            color: var(--navy);
            margin-bottom: 1rem;
        }

        .practice-problems p {
            padding: 0.5rem 0;
            border-bottom: 1px dashed var(--gray-300);
        }

        .practice-problems p:last-child {
            border-bottom: none;
        }

        /* ========================================
           SIGMA NOTATION VISUALIZER
           ======================================== */
        .sigma-visualizer {
            background: var(--navy);
            border-radius: var(--radius-md);
            padding: 2rem;
            min-height: 300px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 1.5rem;
        }

        .sigma-display {
            font-size: 2.5rem;
            color: var(--white);
            font-family: 'Courier New', monospace;
            text-align: center;
            padding: 1rem;
            background: rgba(255, 255, 255, 0.1);
            border-radius: var(--radius-md);
            width: 100%;
            max-width: 600px;
        }

        .sigma-explanation {
            color: var(--white);
            text-align: center;
            max-width: 600px;
            line-height: 1.6;
        }

        .sigma-controls {
            display: flex;
            gap: 1rem;
            flex-wrap: wrap;
            justify-content: center;
            margin-top: 1rem;
        }

        .sigma-parts {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            flex-wrap: wrap;
            justify-content: center;
            margin: 1rem 0;
        }

        .sigma-part {
            background: var(--teal);
            color: var(--navy);
            padding: 0.5rem 1rem;
            border-radius: var(--radius-md);
            font-weight: 600;
            display: flex;
            flex-direction: column;
            align-items: center;
            min-width: 80px;
        }

        .sigma-part-label {
            font-size: 0.8rem;
            opacity: 0.8;
        }

        .sigma-part-value {
            font-size: 1.2rem;
            font-weight: 700;
        }

        /* ========================================
           GEOMETRIC SERIES CALCULATOR
           ======================================== */
        .calculator-container {
            background: var(--navy);
            border-radius: var(--radius-md);
            padding: 2rem;
            min-height: 300px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 1.5rem;
        }

        .calculator-form {
            width: 100%;
            max-width: 500px;
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .calculator-input-group {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1rem;
        }

        @media (max-width: 600px) {
            .calculator-input-group {
                grid-template-columns: 1fr;
            }
        }

        .calculator-input-wrapper {
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
        }

        .calculator-input-wrapper label {
            color: var(--white);
            font-weight: 500;
        }

        .calculator-input {
            padding: 0.75rem;
            border-radius: var(--radius-md);
            border: 2px solid var(--gray-500);
            font-family: inherit;
            font-size: 1rem;
            transition: border-color var(--transition-fast);
        }

        .calculator-input:focus {
            outline: none;
            border-color: var(--teal);
        }

        .calculator-result {
            background: rgba(255, 255, 255, 0.1);
            color: var(--white);
            padding: 1.5rem;
            border-radius: var(--radius-md);
            margin-top: 1rem;
            display: none;
            width: 100%;
            max-width: 500px;
        }

        .calculator-result.show {
            display: block;
            animation: fadeIn 0.5s ease;
        }

        /* ========================================
           QUIZ SECTION STYLES
           ======================================== */
        .quiz-container p {
            color: var(--gray-600);
            margin-bottom: 1.5rem;
        }

        .quiz-question {
            background: var(--gray-50);
            border-radius: var(--radius-md);
            padding: 1.5rem;
            margin-bottom: 1.5rem;
        }

        .quiz-question h4 {
            color: var(--navy);
            font-size: 1.05rem;
            margin-bottom: 1rem;
        }

        .quiz-options {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .quiz-option {
            padding: 1rem 1.25rem;
            background: var(--white);
            border: 2px solid var(--gray-200);
            border-radius: var(--radius-md);
            cursor: pointer;
            transition: all var(--transition-fast);
            font-size: 0.95rem;
        }

        .quiz-option:hover:not(.disabled) {
            border-color: var(--teal);
            background: rgba(0, 212, 170, 0.05);
        }

        .quiz-option.correct {
            border-color: var(--success);
            background: var(--success-light);
        }

        .quiz-option.incorrect {
            border-color: var(--error);
            background: var(--error-light);
        }

        .quiz-option.disabled {
            cursor: not-allowed;
            opacity: 0.7;
        }

        .quiz-feedback {
            margin-top: 1rem;
            padding: 1rem;
            border-radius: var(--radius-md);
            display: none;
            background: var(--gray-100);
            border-left: 4px solid var(--teal);
        }

        .quiz-feedback.show {
            display: block;
            animation: fadeIn 0.3s ease;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .quiz-reset {
            text-align: center;
            margin-top: 1.5rem;
        }

        /* ========================================
           VIDEO SECTION STYLES
           ======================================== */
        .video-container {
            position: relative;
            width: 100%;
            padding-bottom: 56.25%;
            background: var(--navy);
            border-radius: var(--radius-md);
            overflow: hidden;
            margin: 1rem 0;
        }

        .video-container iframe {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            border: none;
        }

        .video-placeholder {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            color: var(--gray-400);
            gap: 1rem;
        }

        .play-btn {
            width: 70px;
            height: 70px;
            background: var(--teal);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all var(--transition-normal);
            box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4);
            animation: pulse 2s infinite;
        }

        .play-btn:hover {
            transform: scale(1.1);
            background: var(--teal-light);
        }

        @keyframes pulse {
            0% { box-shadow: 0 0 0 0 rgba(0, 212, 170, 0.4); }
            70% { box-shadow: 0 0 0 20px rgba(0, 212, 170, 0); }
            100% { box-shadow: 0 0 0 0 rgba(0, 212, 170, 0); }
        }

        /* ========================================
           TUTOR CTA SECTION
           ======================================== */
        .tutor-cta {
            background: linear-gradient(135deg, var(--navy), var(--navy-light));
            border-radius: var(--radius-lg);
            padding: 2.5rem;
            text-align: center;
            color: var(--white);
            position: relative;
            overflow: hidden;
        }

        .tutor-cta::before {
            content: '';
            position: absolute;
            top: -50%;
            right: -50%;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle, rgba(0, 212, 170, 0.15) 0%, transparent 70%);
        }

        .tutor-cta h3 {
            font-size: 1.5rem;
            margin-bottom: 0.75rem;
            position: relative;
        }

        .tutor-cta p {
            color: var(--gray-300);
            position: relative;
        }

        .tutor-cta a {
            color: var(--teal-light);
        }

        /* ========================================
           BUTTONS
           ======================================== */
        .btn-primary {
            background: linear-gradient(135deg, var(--teal), var(--teal-dark));
            color: var(--navy);
            border: none;
            padding: 0.875rem 2rem;
            border-radius: var(--radius-xl);
            font-family: inherit;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
            box-shadow: var(--shadow-md);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-lg);
        }

        .btn-secondary {
            background: var(--white);
            color: var(--navy);
            border: 2px solid var(--gray-200);
            padding: 0.75rem 1.5rem;
            border-radius: var(--radius-xl);
            font-family: inherit;
            font-size: 0.9rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
        }

        .btn-secondary:hover {
            border-color: var(--teal);
            color: var(--teal-dark);
        }

        .btn-gold {
            background: linear-gradient(135deg, var(--gold), var(--gold-dark));
            color: var(--navy);
            border: none;
            padding: 0.75rem 1.5rem;
            border-radius: var(--radius-xl);
            font-family: inherit;
            font-size: 0.9rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
            box-shadow: var(--shadow-md);
        }

        .btn-gold:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-lg);
            background: linear-gradient(135deg, var(--gold-light), var(--gold));
        }

        /* ========================================
           FLOATING TUTOR BUTTON
           ======================================== */
        .floating-tutor {
            position: fixed;
            bottom: 90px;
            right: 1.5rem;
            width: 60px;
            height: 60px;
            background: linear-gradient(135deg, var(--teal), var(--teal-dark));
            color: var(--navy);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.75rem;
            cursor: pointer;
            box-shadow: var(--shadow-lg);
            z-index: 998;
            transition: all var(--transition-fast);
        }

        .floating-tutor:hover {
            transform: scale(1.1);
            box-shadow: 0 8px 30px rgba(0, 212, 170, 0.4);
        }

        /* ========================================
           MODAL STYLES
           ======================================== */
        .modal {
            position: fixed;
            inset: 0;
            background: rgba(10, 22, 40, 0.8);
            backdrop-filter: blur(4px);
            z-index: 2000;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 1.5rem;
            opacity: 0;
            visibility: hidden;
            transition: all var(--transition-normal);
        }

        .modal.active {
            opacity: 1;
            visibility: visible;
        }

        .modal-content {
            background: var(--white);
            border-radius: var(--radius-lg);
            max-width: 450px;
            width: 100%;
            transform: scale(0.9) translateY(20px);
            transition: all var(--transition-normal);
            overflow: hidden;
        }

        .modal.active .modal-content {
            transform: scale(1) translateY(0);
        }

        .modal-header {
            background: linear-gradient(135deg, var(--navy), var(--navy-light));
            padding: 1.25rem 1.5rem;
            color: var(--white);
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .modal-header h2 {
            font-size: 1.15rem;
        }

        .close-btn {
            background: none;
            border: none;
            color: var(--gray-300);
            font-size: 1.75rem;
            cursor: pointer;
            line-height: 1;
            transition: color var(--transition-fast);
        }

        .close-btn:hover {
            color: var(--white);
        }

        .modal-content > p,
        .modal-content > form {
            padding: 0 1.5rem;
        }

        .modal-content > p {
            padding-top: 1.5rem;
        }

        .modal-content > form {
            padding-bottom: 1.5rem;
        }

        .modal-content input,
        .modal-content textarea {
            width: 100%;
            padding: 0.75rem;
            border: 2px solid var(--gray-200);
            border-radius: var(--radius-md);
            font-family: inherit;
            font-size: 0.95rem;
            transition: border-color var(--transition-fast);
        }

        .modal-content input:focus,
        .modal-content textarea:focus {
            outline: none;
            border-color: var(--teal);
        }

        /* ========================================
           FOOTER NAVIGATION
           ======================================== */
        .lesson-nav {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background: var(--white);
            box-shadow: 0 -4px 16px rgba(10, 22, 40, 0.1);
            padding: 0.75rem 1.5rem;
            z-index: 997;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .nav-btn {
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            padding: 0.625rem 1.25rem;
            border-radius: var(--radius-md);
            font-family: inherit;
            font-size: 0.9rem;
            font-weight: 600;
            cursor: pointer;
            transition: all var(--transition-fast);
            text-decoration: none;
            background: var(--gray-100);
            color: var(--gray-600);
            border: none;
        }

        .nav-btn:hover {
            background: var(--gray-200);
            color: var(--navy);
        }

        .nav-btn.primary {
            background: linear-gradient(135deg, var(--teal), var(--teal-dark));
            color: var(--navy);
            box-shadow: var(--shadow-sm);
        }

        .nav-btn.primary:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-md);
        }

        .nav-center {
            display: flex;
        }

        /* ========================================
           GEOMETRIC SERIES SPECIFIC STYLES
           ======================================== */
        .formula-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 1rem;
            margin: 1.5rem 0;
        }

        .formula-card {
            background: linear-gradient(135deg, var(--navy-light), var(--navy));
            color: var(--white);
            padding: 1.5rem;
            border-radius: var(--radius-md);
            text-align: center;
        }

        .formula-card.gold {
            background: linear-gradient(135deg, #ff9800, #ffb74d);
            color: var(--navy);
        }

        .formula-card h4 {
            color: var(--teal-light);
            margin-bottom: 0.75rem;
            font-size: 1.1rem;
        }

        .formula-card.gold h4 {
            color: var(--navy);
        }

        .formula-card .formula {
            font-family: 'Courier New', monospace;
            font-size: 1.25rem;
            margin: 0.75rem 0;
        }

        .formula-card .description {
            color: var(--gray-300);
            font-size: 0.9rem;
        }

        .formula-card.gold .description {
            color: rgba(26, 39, 68, 0.8);
        }

        .teacher-learner-table {
            width: 100%;
            border-collapse: collapse;
            margin: 1.5rem 0;
            background: var(--white);
            border-radius: var(--radius-md);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
        }

        .teacher-learner-table th {
            background: var(--navy);
            color: var(--white);
            padding: 1rem;
            text-align: left;
            font-weight: 600;
        }

        .teacher-learner-table td {
            padding: 1rem;
            border: 1px solid var(--gray-200);
            vertical-align: top;
        }

        .teacher-learner-table .teacher-col {
            background: rgba(0, 212, 170, 0.05);
            border-right: 2px solid var(--teal);
        }

        .teacher-learner-table .learner-col {
            background: rgba(26, 39, 68, 0.05);
        }

        .lesson-timeline {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
            margin: 1.5rem 0;
        }

        .timeline-item {
            background: var(--gray-50);
            padding: 1.25rem;
            border-radius: var(--radius-md);
            border-left: 4px solid var(--teal);
        }

        .timeline-item.gold {
            border-left: 4px solid var(--gold);
        }

        .timeline-item .time-badge {
            display: inline-block;
            background: var(--teal);
            color: var(--navy);
            padding: 0.25rem 0.75rem;
            border-radius: var(--radius-sm);
            font-weight: 600;
            font-size: 0.85rem;
            margin-bottom: 0.75rem;
        }

        .timeline-item.gold .time-badge {
            background: var(--gold);
        }

        .sigma-notation-box {
            background: linear-gradient(135deg, var(--navy-light), var(--navy));
            color: var(--white);
            padding: 1.5rem;
            border-radius: var(--radius-md);
            margin: 1.5rem 0;
            font-family: 'Courier New', monospace;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .sigma-notation-box::before {
            content: 'Î£';
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            font-size: 8rem;
            opacity: 0.1;
            color: var(--teal);
        }

        .terms-list {
            display: flex;
            flex-wrap: wrap;
            gap: 0.5rem;
            justify-content: center;
            margin: 1rem 0;
        }

        .term-box {
            background: var(--teal);
            color: var(--navy);
            padding: 0.5rem 1rem;
            border-radius: var(--radius-sm);
            font-weight: 600;
            min-width: 40px;
            text-align: center;
        }

        .term-box.gold {
            background: var(--gold);
        }

        /* ========================================
           RESPONSIVE STYLES
           ======================================== */
        @media (max-width: 768px) {
            header {
                padding: 0 1rem;
                height: 60px;
            }

            header nav span {
                font-size: 1.1rem !important;
            }

            .sticky-nav {
                top: 60px;
                padding: 0.5rem;
            }

            .lesson-map {
                gap: 0.25rem;
            }

            .nav-link {
                padding: 0.4rem 0.6rem;
                font-size: 0.75rem;
            }

            main {
                margin-top: 115px;
