            .section-content {
                padding: 1rem;
            }

            .formula-box {
                font-size: 0.95rem;
                padding: 1rem;
            }

            .worked-example {
                padding: 1rem;
            }

            .sigma-visualizer, .calculator-container {
                padding: 1.5rem;
            }

            .sigma-display {
                font-size: 1.8rem;
            }

            .tutor-cta {
                padding: 1.75rem;
            }

            .tutor-cta h3 {
                font-size: 1.25rem;
            }

            .floating-tutor {
                width: 50px;
                height: 50px;
                font-size: 1.5rem;
                bottom: 80px;
                right: 1rem;
            }

            .lesson-nav {
                padding: 0.5rem 1rem;
            }

            .nav-btn {
                padding: 0.5rem 0.875rem;
                font-size: 0.8rem;
            }

            .nav-center .nav-btn span {
                display: none;
            }

            .modal-content {
                margin: 1rem;
            }

            .formula-grid {
                grid-template-columns: 1fr;
            }

            .sigma-parts {
                flex-direction: column;
            }

            .sigma-part {
                min-width: 120px;
            }
        }

        @media (max-width: 480px) {
            header nav span {
                font-size: 0.95rem !important;
            }

            .logo img {
                height: 36px;
            }

            .nav-link {
                padding: 0.35rem 0.5rem;
                font-size: 0.7rem;
            }

            .step-list li {
